CREATE OR ALTER VIEW acta.alerts_view AS
SELECT
    a.id AS alert_id,
    a.alert_ref,
    ns.name AS namespace,
    a.job_id,
    a.job_ref,
    j.definition_id,
    d.name AS job_name,
    CASE a.origin_code WHEN 10 THEN 'automatic' WHEN 20 THEN 'manual' END AS origin,
    a.origin_code,
    CASE a.severity_code WHEN 10 THEN 'info' WHEN 20 THEN 'warning' WHEN 30 THEN 'error' WHEN 40 THEN 'critical' END AS severity,
    a.severity_code,
    CASE a.kind_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'first-failure' WHEN 20 THEN 'threshold-reached' WHEN 30 THEN 'final-failure' WHEN 40 THEN 'manual' END AS kind,
    a.kind_code,
    CASE a.delivery_status_code WHEN 10 THEN 'pending' WHEN 20 THEN 'retry-after' WHEN 30 THEN 'suppressed' WHEN 100 THEN 'delivered' WHEN 200 THEN 'failed' END AS delivery_status,
    a.delivery_status_code,
    a.title,
    a.message,
    a.channel_name,
    a.dedupe_key AS deduplication_key,
    a.dedupe_window_start_utc,
    a.occurrence_count,
    a.resolved_at_utc,
    a.retry_count,
    a.retry_after_utc,
    a.created_at_utc,
    a.modified_at_utc,
    a.version
FROM acta.alerts AS a
JOIN acta.namespaces AS ns ON ns.id = a.namespace_id
LEFT JOIN acta.jobs AS j ON j.id = a.job_id
LEFT JOIN acta.definitions AS d ON d.id = j.definition_id
GO
CREATE OR ALTER VIEW acta.checkpoints_view AS
SELECT
    c.job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    c.name AS checkpoint_name,
    CASE c.kind_code WHEN 10 THEN 'variable' WHEN 20 THEN 'signal' WHEN 30 THEN 'timer' WHEN 40 THEN 'progress' WHEN 50 THEN 'child-latch' END AS kind,
    c.kind_code,
    CASE c.status_code WHEN 10 THEN 'pending' WHEN 20 THEN 'set' WHEN 100 THEN 'consumed' END AS state,
    c.status_code,
    c.due_at_utc,
    CASE c.value_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', c.value_format_id)
    END AS value_format,
    CASE
        WHEN
            c.value_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(c.value AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS value_text,
    c.created_at_utc,
    c.modified_at_utc,
    c.version
FROM acta.checkpoints AS c
JOIN acta.jobs AS j ON j.id = c.job_id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
GO
CREATE OR ALTER VIEW acta.definitions_view AS
SELECT
    d.id AS definition_id,
    ns.name AS namespace,
    d.name AS job_name,
    CASE d.status_code WHEN 10 THEN 'active' WHEN 240 THEN 'retired' END AS status,
    d.status_code,
    d.definition_hash,
    d.manifest_generation_at_utc,
    d.input_type_name,
    d.input_format_name,
    d.output_type_name,
    d.output_format_name,
    CASE d.priority_code_effective WHEN 0 THEN 'bulk' WHEN 50 THEN 'normal' WHEN 70 THEN 'high' WHEN 85 THEN 'critical' WHEN 100 THEN 'realtime' END AS priority,
    d.priority_code_effective AS priority_code,
    d.priority_code AS priority_default_code,
    d.priority_code_override AS priority_override_code,
    d.max_attempts_effective AS max_attempts,
    d.max_attempts AS max_attempts_default,
    d.max_attempts_override,
    d.backoff_effective AS backoff,
    d.backoff AS backoff_default,
    d.backoff_override,
    d.execution_timeout_seconds_effective AS execution_timeout_seconds,
    d.execution_timeout_seconds AS execution_timeout_seconds_default,
    d.execution_timeout_seconds_override,
    d.deadline_seconds_effective AS deadline_seconds,
    d.deadline_seconds AS deadline_seconds_default,
    d.deadline_seconds_override,
    CASE d.deadline_behavior_code_effective WHEN 10 THEN 'strict' WHEN 20 THEN 'advisory' END AS deadline_behavior,
    d.deadline_behavior_code_effective AS deadline_behavior_code,
    d.deadline_behavior_code AS deadline_behavior_default_code,
    d.deadline_behavior_code_override AS deadline_behavior_override_code,
    d.retention_seconds_effective AS retention_seconds,
    d.retention_seconds AS retention_seconds_default,
    d.retention_seconds_override,
    CASE d.audit_level_code_effective WHEN 0 THEN 'off' WHEN 10 THEN 'failures' WHEN 20 THEN 'audit' END AS audit_level,
    d.audit_level_code_effective AS audit_level_code,
    d.audit_level_code AS audit_level_default_code,
    d.audit_level_code_override AS audit_level_override_code,
    CASE d.alert_profile_code_effective WHEN 0 THEN 'none' WHEN 10 THEN 'on-failure' WHEN 20 THEN 'info' WHEN 30 THEN 'on-terminal' WHEN 40 THEN 'sys-critical' END AS alert_profile,
    d.alert_profile_code_effective AS alert_profile_code,
    d.alert_profile_code AS alert_profile_default_code,
    d.alert_profile_code_override AS alert_profile_override_code,
    d.alert_channel_name_effective AS alert_channel_name,
    d.alert_channel_name AS alert_channel_name_default,
    d.alert_channel_name_override,
    d.runbook_url_effective AS runbook_url,
    d.runbook_url AS runbook_url_default,
    d.runbook_url_override,
    d.created_at_utc,
    d.modified_at_utc,
    d.version
FROM acta.definitions AS d
JOIN acta.namespaces AS ns ON ns.id = d.namespace_id
GO
CREATE OR ALTER VIEW acta.jobs_view AS
SELECT
    j.id AS job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    CASE r.status_code WHEN 10 THEN 'ready' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 40 THEN 'dispatched' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS status,
    r.status_code,
    j.deduplication_key,
    j.correlation_key,
    j.exclusive_key,
    j.parent_id,
    COALESCE(j.lineage_root_id, j.id) AS lineage_root_job_id,
    root.job_ref AS lineage_root_job_ref,
    j.tenant_id,
    t.tenant_key,
    CASE r.priority_code WHEN 0 THEN 'bulk' WHEN 50 THEN 'normal' WHEN 70 THEN 'high' WHEN 85 THEN 'critical' WHEN 100 THEN 'realtime' END AS priority,
    r.priority_code,
    CASE j.input_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', j.input_format_id)
    END AS input_format,
    CASE
        WHEN
            j.input_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(j.input AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS input_text,
    lr.execution_number AS last_result_execution_number,
    CASE lr.result_format_id
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CASE WHEN lr.result_format_id IS NULL THEN NULL ELSE CONCAT('custom-', lr.result_format_id) END
    END AS last_result_format,
    CASE
        WHEN
            lr.result_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(lr.result AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS last_result_text,
    lr.created_at_utc AS last_result_created_at_utc,
    r.next_run_at_utc,
    r.execution_number,
    r.failure_count,
    r.leased_by_worker_id,
    w.host AS leased_by_worker_host,
    r.lease_expires_at_utc,
    r.retention_until_utc,
    j.created_at_utc,
    r.modified_at_utc,
    r.version
FROM acta.jobs AS j
JOIN acta.runtimes AS r ON r.job_id = j.id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
LEFT JOIN acta.jobs AS root ON root.id = COALESCE(j.lineage_root_id, j.id)
LEFT JOIN acta.tenants AS t ON t.id = j.tenant_id
LEFT JOIN acta.workers AS w ON w.id = r.leased_by_worker_id
LEFT JOIN acta.results AS lr
    ON
        lr.job_id = j.id
        AND lr.execution_number = (
            SELECT MAX(rr.execution_number) FROM acta.results AS rr
            WHERE rr.job_id = j.id
        )
GO
CREATE OR ALTER VIEW acta.schedules_view AS
SELECT
    s.id AS schedule_id,
    ns.name AS namespace,
    s.job_id,
    j.job_ref,
    s.definition_id,
    d.name AS job_name,
    s.name AS schedule_name,
    CASE s.origin_code WHEN 20 THEN 'operator' WHEN 40 THEN 'definition' END AS origin,
    s.origin_code,
    CASE s.status_code WHEN 10 THEN 'active' WHEN 30 THEN 'paused' WHEN 230 THEN 'orphaned' END AS status,
    s.status_code,
    s.expression_effective,
    s.expression,
    s.expression_override,
    s.time_zone_id_effective,
    s.time_zone_id,
    s.time_zone_id_override,
    CASE s.expression_kind_code WHEN 10 THEN 'cron' WHEN 20 THEN 'interval' END AS expression_kind,
    s.expression_kind_code,
    CASE s.misfire_strategy_code WHEN 10 THEN 'catch-up-once' WHEN 20 THEN 'skip' END AS misfire_strategy,
    s.misfire_strategy_code,
    s.next_run_at_utc,
    s.last_occurrence_at_utc,
    s.paused_until_utc,
    s.description,
    s.reason_message,
    s.created_at_utc,
    s.modified_at_utc,
    s.version
FROM acta.schedules AS s
JOIN acta.namespaces AS ns ON ns.id = s.namespace_id
JOIN acta.jobs AS j ON j.id = s.job_id
JOIN acta.definitions AS d ON d.id = s.definition_id
GO
CREATE OR ALTER VIEW acta.steps_view AS
SELECT
    s.id AS step_id,
    s.job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    s.name AS step_name,
    CASE s.status_code WHEN 10 THEN 'pending' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'exhausted' WHEN 230 THEN 'interrupted' END AS state,
    s.status_code,
    s.attempt_number,
    s.next_retry_at_utc,
    CASE s.reason_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'job.unclassified' WHEN 20 THEN 'job.unhandled-exception' WHEN 21 THEN 'job.lease-expired' WHEN 22 THEN 'job.execution-timeout' WHEN 23 THEN 'job.non-retryable-exception' WHEN 24 THEN 'job.deadline-exceeded' WHEN 25 THEN 'job.attempt-aborted' WHEN 30 THEN 'job.schedules-exhausted' WHEN 40 THEN 'job.control-manual' WHEN 41 THEN 'job.parent-cancelled' WHEN 42 THEN 'job.definition-retired' WHEN 50 THEN 'job.handler-rescheduled' WHEN 51 THEN 'job.handler-suspended' WHEN 52 THEN 'job.handler-failed' WHEN 53 THEN 'job.handler-cancelled' WHEN 54 THEN 'job.handler-paused' WHEN 60 THEN 'job.signal-released' WHEN 61 THEN 'job.step-retry-scheduled' WHEN 62 THEN 'job.exclusive-key-held' WHEN 63 THEN 'job.step-interrupted' WHEN 64 THEN 'job.result-oversized' WHEN 100 THEN 'worker.clean-shutdown' WHEN 101 THEN 'worker.heartbeat-stale' END AS reason,
    s.reason_code,
    s.reason_message,
    CASE s.result_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', s.result_format_id)
    END AS result_format,
    CASE
        WHEN
            s.result_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(s.result AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS result_text,
    s.created_at_utc,
    s.modified_at_utc,
    s.version
FROM acta.steps AS s
JOIN acta.jobs AS j ON j.id = s.job_id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
GO
CREATE OR ALTER VIEW acta.workers_view AS
SELECT
    w.id AS worker_id,
    w.worker_ref,
    ns.name AS namespace,
    CASE w.status_code WHEN 10 THEN 'active' WHEN 80 THEN 'draining' WHEN 100 THEN 'stopped' WHEN 200 THEN 'dead' END AS status,
    w.status_code,
    w.deployment_version,
    w.host,
    w.engine_version,
    w.dotnet_version,
    w.process_id,
    w.max_concurrency,
    w.last_seen_at_utc,
    w.created_at_utc,
    w.modified_at_utc,
    w.version
FROM acta.workers AS w
JOIN acta.namespaces AS ns ON ns.id = w.namespace_id
GO
CREATE OR ALTER VIEW acta.events_view AS
SELECT
    e.id AS event_id,
    e.created_at_utc,
    ns.name AS namespace,
    e.job_id,
    e.job_ref,
    e.lineage_root_id AS lineage_root_job_id,
    root.job_ref AS lineage_root_job_ref,
    e.definition_id,
    d.name AS job_name,
    CASE e.event_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'tenant.suspended' WHEN 11 THEN 'tenant.resumed' WHEN 12 THEN 'tenant.updated' WHEN 20 THEN 'namespace.suspended' WHEN 21 THEN 'namespace.resumed' WHEN 22 THEN 'namespace.updated' WHEN 30 THEN 'definition.overrides-updated' WHEN 40 THEN 'job.execution-started' WHEN 41 THEN 'job.execution-finished' WHEN 50 THEN 'job.recurring-rolled-over' WHEN 60 THEN 'job.suspended' WHEN 61 THEN 'job.rescheduled' WHEN 70 THEN 'job.cancelled' WHEN 71 THEN 'job.paused' WHEN 72 THEN 'job.resumed' WHEN 73 THEN 'job.restarted' WHEN 74 THEN 'job.reprioritized' WHEN 75 THEN 'job.purged' WHEN 76 THEN 'job.input-amended' WHEN 80 THEN 'job.signal-raised' WHEN 81 THEN 'job.state-reset' WHEN 90 THEN 'job.note-recorded' WHEN 100 THEN 'schedule.paused' WHEN 101 THEN 'schedule.resumed' WHEN 102 THEN 'schedule.pause-expired' WHEN 103 THEN 'schedule.overrides-updated' WHEN 104 THEN 'schedule.triggered' WHEN 120 THEN 'worker.started' WHEN 121 THEN 'worker.stopped' WHEN 122 THEN 'worker.died' WHEN 140 THEN 'alert.acknowledged' WHEN 141 THEN 'alert.resolved' WHEN 160 THEN 'setting.updated' WHEN 180 THEN 'outbox.requeued' WHEN 181 THEN 'outbox.discarded' END AS event,
    e.event_code,
    CASE e.actor_code WHEN 10 THEN 'sys' WHEN 20 THEN 'operator' WHEN 50 THEN 'job' WHEN 70 THEN 'worker' END AS actor,
    e.actor_code,
    e.actor_key,
    CASE e.from_status_code WHEN 10 THEN 'ready' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 40 THEN 'dispatched' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS from_status,
    e.from_status_code,
    CASE e.to_status_code WHEN 10 THEN 'ready' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 40 THEN 'dispatched' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS to_status,
    e.to_status_code,
    CASE e.execution_status_code WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 150 THEN 'rescheduled' WHEN 151 THEN 'suspended' WHEN 152 THEN 'paused' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' WHEN 230 THEN 'orphaned' END AS execution_status,
    e.execution_status_code,
    CASE e.reason_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'job.unclassified' WHEN 20 THEN 'job.unhandled-exception' WHEN 21 THEN 'job.lease-expired' WHEN 22 THEN 'job.execution-timeout' WHEN 23 THEN 'job.non-retryable-exception' WHEN 24 THEN 'job.deadline-exceeded' WHEN 25 THEN 'job.attempt-aborted' WHEN 30 THEN 'job.schedules-exhausted' WHEN 40 THEN 'job.control-manual' WHEN 41 THEN 'job.parent-cancelled' WHEN 42 THEN 'job.definition-retired' WHEN 50 THEN 'job.handler-rescheduled' WHEN 51 THEN 'job.handler-suspended' WHEN 52 THEN 'job.handler-failed' WHEN 53 THEN 'job.handler-cancelled' WHEN 54 THEN 'job.handler-paused' WHEN 60 THEN 'job.signal-released' WHEN 61 THEN 'job.step-retry-scheduled' WHEN 62 THEN 'job.exclusive-key-held' WHEN 63 THEN 'job.step-interrupted' WHEN 64 THEN 'job.result-oversized' WHEN 100 THEN 'worker.clean-shutdown' WHEN 101 THEN 'worker.heartbeat-stale' END AS reason,
    e.reason_code,
    e.reason_message,
    CASE e.detail_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CONCAT('custom-', e.detail_format_id)
    END AS detail_format,
    CASE
        WHEN
            e.detail_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */)
            THEN CAST(e.detail AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8
    END AS detail_text,
    e.worker_id,
    wkr.worker_ref,
    e.execution_number,
    e.duration_ms,
    e.tenant_id
FROM acta.events AS e
JOIN acta.namespaces AS ns ON ns.id = e.namespace_id
LEFT JOIN acta.definitions AS d ON d.id = e.definition_id
LEFT JOIN acta.jobs AS root ON root.id = e.lineage_root_id
LEFT JOIN acta.workers AS wkr ON wkr.id = e.worker_id
GO
CREATE OR ALTER VIEW acta.tags_view AS
SELECT
    CASE t.scope_code WHEN 20 THEN 'tenant' WHEN 30 THEN 'namespace' WHEN 40 THEN 'definition' WHEN 50 THEN 'job' WHEN 60 THEN 'schedule' WHEN 70 THEN 'worker' WHEN 80 THEN 'alert' WHEN 90 THEN 'event' END AS scope,
    t.scope_code,
    t.scope_id,
    ns.name AS namespace,
    t.namespace_id,
    t.name AS tag_name,
    t.value AS tag_value,
    t.value_search AS tag_value_search
FROM acta.tags AS t
LEFT JOIN acta.namespaces AS ns ON ns.id = t.namespace_id
GO
-- ===== routines (versionless; always rewritten to this file's definitions) =====
GO
CREATE OR ALTER PROCEDURE acta.acknowledge_job_alert
    @p_alert_ref UNIQUEIDENTIFIER,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE
        @namespace_id SMALLINT, @job_id BIGINT, @job_ref UNIQUEIDENTIFIER,
        @ack DATETIME2(7), @resolved DATETIME2(7),
        @definition_id INT, @lineage_root_id BIGINT, @execution_number INT;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @namespace_id = a.namespace_id,
            @job_id = a.job_id,
            @job_ref = a.job_ref,
            @ack = a.acknowledged_at_utc,
            @resolved = a.resolved_at_utc
        FROM acta.alerts a WITH (UPDLOCK, ROWLOCK)
        WHERE a.alert_ref = @p_alert_ref;

        IF @namespace_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS DATETIME2(7)) AS acknowledged_at_utc,
                    CAST(NULL AS DATETIME2(7)) AS resolved_at_utc;
                RETURN;
            END;

        IF @ack IS NOT NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
                    @ack AS acknowledged_at_utc,
                    @resolved AS resolved_at_utc;
                RETURN;
            END;

        SELECT
            @definition_id = j.definition_id,
            @lineage_root_id = j.lineage_root_id
        FROM acta.jobs j
        WHERE j.id = @job_id;
        SELECT @execution_number = r.execution_number
        FROM acta.runtimes r
        WHERE r.job_id = @job_id;

        SET @ack = @now;

        UPDATE acta.alerts
        SET
            acknowledged_at_utc = @ack,
            modified_at_utc = @now,
            version = version + 1
        WHERE alert_ref = @p_alert_ref;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor_key,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        VALUES (
            140 /* EventCode.AlertAcknowledged */, @now, @namespace_id,
            @p_actor_code, @p_actor_key,
            @job_id, @job_ref, @execution_number,
            COALESCE(@lineage_root_id, @job_id), @definition_id,
            NULL,
            NULL, NULL,
            NULL, NULL,
            NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @ack AS acknowledged_at_utc,
            @resolved AS resolved_at_utc;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.raise_job_alert
    @p_namespace_name VARCHAR(128),
    @p_job_id BIGINT,
    @p_origin_code TINYINT,
    @p_severity_code TINYINT,
    @p_kind_code TINYINT,
    @p_title NVARCHAR(512),
    @p_message NVARCHAR(512),
    @p_channel_name VARCHAR(128),
    @p_delivery_status_code TINYINT,
    @p_dedupe_key VARCHAR(512),
    @p_dedupe_window_start_utc DATETIME2(3),
    @p_source_event_id BIGINT,
    @p_alert_ref UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    DECLARE @v_ns SMALLINT = (
        SELECT id FROM acta.namespaces
        WHERE name = @p_namespace_name
    );
    IF @v_ns IS NULL
        THROW 50000, 'raise_job_alert: unknown namespace', 1;

    DECLARE @v_job_ref UNIQUEIDENTIFIER = (
        SELECT job_ref FROM acta.jobs
        WHERE id = @p_job_id
    );

    IF @p_job_id IS NOT NULL AND @v_job_ref IS NULL
        THROW 50007, 'ACTA:ALERT_UNKNOWN_JOB:raise_job_alert: unknown job id', 1;

    IF @p_dedupe_key IS NULL
        BEGIN
            INSERT INTO acta.alerts (
                namespace_id, alert_ref, job_id, job_ref,
                origin_code, severity_code, kind_code, title, message, channel_name,
                dedupe_key, dedupe_window_start_utc, occurrence_count, last_projected_event_id,
                delivery_status_code, retry_count,
                created_at_utc, modified_at_utc, version
            )
            VALUES (
                @v_ns, @p_alert_ref, @p_job_id, @v_job_ref,
                @p_origin_code, @p_severity_code, @p_kind_code, @p_title, @p_message, @p_channel_name,
                NULL, NULL, 1, @p_source_event_id,
                @p_delivery_status_code, 0,
                @now, @now, 0
            );
            SELECT 1;
            RETURN;
        END

    DECLARE @updated TABLE (occurrence_count INT NOT NULL);

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE ja
        SET
            job_id = @p_job_id,
            job_ref = @v_job_ref,
            origin_code = @p_origin_code,
            severity_code = @p_severity_code,
            kind_code = @p_kind_code,
            title = @p_title,
            message = @p_message,
            channel_name = @p_channel_name,
            occurrence_count = ja.occurrence_count + 1,
            resolved_at_utc = NULL,
            last_projected_event_id = COALESCE(@p_source_event_id, ja.last_projected_event_id),
            modified_at_utc = @now,
            version = ja.version + 1
        OUTPUT INSERTED.occurrence_count INTO @updated
        FROM acta.alerts AS ja WITH (UPDLOCK, HOLDLOCK, INDEX (ux_alerts_dedupe))
        WHERE
            ja.namespace_id = @v_ns
            AND ja.dedupe_key = @p_dedupe_key
            AND ja.dedupe_window_start_utc = @p_dedupe_window_start_utc
            AND (
                @p_source_event_id IS NULL
                OR ja.last_projected_event_id IS NULL
                OR @p_source_event_id > ja.last_projected_event_id
            );

        IF NOT EXISTS (SELECT 1 FROM @updated)
            BEGIN
                -- Either no row is there yet and this raise inserts it, or one is and this is a replay
                -- of an event it already absorbed. Reading under the range lock the UPDATE already
                -- took tells the two apart without a race.
                DECLARE @v_existing_count INT = (
                    SELECT ja.occurrence_count
                    FROM acta.alerts AS ja WITH (UPDLOCK, HOLDLOCK, INDEX (ux_alerts_dedupe))
                    WHERE
                        ja.namespace_id = @v_ns
                        AND ja.dedupe_key = @p_dedupe_key
                        AND ja.dedupe_window_start_utc = @p_dedupe_window_start_utc
                );

                IF @v_existing_count IS NULL
                    BEGIN
                        INSERT INTO acta.alerts (
                            namespace_id, alert_ref, job_id, job_ref,
                            origin_code, severity_code, kind_code, title, message, channel_name,
                            dedupe_key, dedupe_window_start_utc, occurrence_count, last_projected_event_id,
                            delivery_status_code, retry_count,
                            created_at_utc, modified_at_utc, version
                        )
                        OUTPUT INSERTED.occurrence_count INTO @updated
                        VALUES (
                            @v_ns, @p_alert_ref, @p_job_id, @v_job_ref,
                            @p_origin_code, @p_severity_code, @p_kind_code, @p_title, @p_message, @p_channel_name,
                            @p_dedupe_key, @p_dedupe_window_start_utc, 1, @p_source_event_id,
                            @p_delivery_status_code, 0,
                            @now, @now, 0
                        );
                    END
                ELSE
                    BEGIN
                        -- A replay: nothing written, and the caller's failure threshold reads the count
                        -- the row already carries.
                        INSERT INTO @updated (occurrence_count) VALUES (@v_existing_count);
                    END
            END

        COMMIT TRANSACTION;

        SELECT TOP (1) occurrence_count FROM @updated;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.resolve_job_alert_manual
    @p_alert_ref UNIQUEIDENTIFIER,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE
        @namespace_id SMALLINT, @job_id BIGINT, @job_ref UNIQUEIDENTIFIER,
        @ack DATETIME2(7), @resolved DATETIME2(7),
        @definition_id INT, @lineage_root_id BIGINT, @execution_number INT;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @namespace_id = a.namespace_id,
            @job_id = a.job_id,
            @job_ref = a.job_ref,
            @ack = a.acknowledged_at_utc,
            @resolved = a.resolved_at_utc
        FROM acta.alerts a WITH (UPDLOCK, ROWLOCK)
        WHERE a.alert_ref = @p_alert_ref;

        IF @namespace_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS DATETIME2(7)) AS acknowledged_at_utc,
                    CAST(NULL AS DATETIME2(7)) AS resolved_at_utc;
                RETURN;
            END;

        IF @resolved IS NOT NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
                    @ack AS acknowledged_at_utc,
                    @resolved AS resolved_at_utc;
                RETURN;
            END;

        SELECT
            @definition_id = j.definition_id,
            @lineage_root_id = j.lineage_root_id
        FROM acta.jobs j
        WHERE j.id = @job_id;
        SELECT @execution_number = r.execution_number
        FROM acta.runtimes r
        WHERE r.job_id = @job_id;

        SET @resolved = @now;

        UPDATE acta.alerts
        SET
            resolved_at_utc = @resolved,
            modified_at_utc = @now,
            version = version + 1
        WHERE alert_ref = @p_alert_ref;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor_key,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        VALUES (
            141 /* EventCode.AlertResolved */, @now, @namespace_id,
            @p_actor_code, @p_actor_key,
            @job_id, @job_ref, @execution_number,
            COALESCE(@lineage_root_id, @job_id), @definition_id,
            NULL,
            NULL, NULL,
            NULL, NULL,
            NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @ack AS acknowledged_at_utc,
            @resolved AS resolved_at_utc;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.checkpoint_slot
    @p_action SMALLINT,
    @p_job_id BIGINT,
    @p_kind_code TINYINT,
    @p_name VARCHAR(128),
    @p_value_format_id TINYINT,
    @p_value VARBINARY(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF
        @p_action IN (10 /* CheckpointSlotAction.Set */, 30 /* CheckpointSlotAction.GetOrSet */)
        AND (@p_value_format_id = 0 /* JobPayloadFormat.None */ OR @p_value IS NULL)
        THROW 50002, 'Variable payload must use a non-zero format id and non-NULL value.', 1;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @row TABLE (
        found INT NOT NULL,
        value_format_id TINYINT NULL,
        value VARBINARY(MAX) NULL,
        version INT NULL
    );

    IF @p_action = 10 /* CheckpointSlotAction.Set */
        BEGIN
            BEGIN TRY
                BEGIN TRANSACTION;

                UPDATE jv
                SET
                    value_format_id = @p_value_format_id,
                    value = @p_value,
                    modified_at_utc = @now,
                    version = version + 1
                FROM acta.checkpoints AS jv WITH (UPDLOCK, HOLDLOCK)
                WHERE
                    jv.job_id = @p_job_id
                    AND jv.kind_code = @p_kind_code
                    AND jv.name = @p_name;

                IF @@ROWCOUNT = 0
                    BEGIN
                        INSERT INTO acta.checkpoints (
                            job_id, kind_code, name,
                            value_format_id, value,
                            created_at_utc, modified_at_utc, version
                        )
                        VALUES (
                            @p_job_id, @p_kind_code, @p_name,
                            @p_value_format_id, @p_value,
                            @now, @now, 0
                        );
                    END

                COMMIT TRANSACTION;
            END TRY
            BEGIN CATCH
                IF XACT_STATE() <> 0
                    BEGIN
                        ROLLBACK TRANSACTION;
                    END;

                THROW;
            END CATCH;

            INSERT INTO @row (found, value_format_id, value, version) VALUES (1, NULL, NULL, NULL);
        END
    ELSE IF @p_action = 20 /* CheckpointSlotAction.Get */
        BEGIN
            INSERT INTO @row (found, value_format_id, value, version)
            SELECT
                1,
                jv.value_format_id,
                jv.value,
                jv.version
            FROM acta.checkpoints AS jv
            WHERE
                jv.job_id = @p_job_id
                AND jv.kind_code = @p_kind_code
                AND jv.name = @p_name;

            IF @@ROWCOUNT = 0
                BEGIN
                    INSERT INTO @row (found, value_format_id, value, version) VALUES (0, NULL, NULL, NULL);
                END
        END
    ELSE IF @p_action = 30 /* CheckpointSlotAction.GetOrSet */
        BEGIN
            BEGIN TRY
                BEGIN TRANSACTION;

                INSERT INTO @row (found, value_format_id, value, version)
                SELECT
                    1,
                    jv.value_format_id,
                    jv.value,
                    jv.version
                FROM acta.checkpoints AS jv WITH (UPDLOCK, HOLDLOCK)
                WHERE
                    jv.job_id = @p_job_id
                    AND jv.kind_code = @p_kind_code
                    AND jv.name = @p_name;

                IF @@ROWCOUNT = 0
                    BEGIN
                        INSERT INTO acta.checkpoints (
                            job_id, kind_code, name,
                            value_format_id, value,
                            created_at_utc, modified_at_utc, version
                        )
                        VALUES (
                            @p_job_id, @p_kind_code, @p_name,
                            @p_value_format_id, @p_value,
                            @now, @now, 0
                        );

                        INSERT INTO @row (found, value_format_id, value, version)
                        VALUES (1, @p_value_format_id, @p_value, 0);
                    END

                COMMIT TRANSACTION;
            END TRY
            BEGIN CATCH
                IF XACT_STATE() <> 0
                    BEGIN
                        ROLLBACK TRANSACTION;
                    END;

                THROW;
            END CATCH;
        END
    ELSE IF @p_action = 40 /* CheckpointSlotAction.Exists */
        BEGIN
            INSERT INTO @row (found, value_format_id, value, version)
            SELECT
                CASE WHEN EXISTS (
                    SELECT 1
                    FROM acta.checkpoints AS jv
                    WHERE
                        jv.job_id = @p_job_id
                        AND jv.kind_code = @p_kind_code
                        AND jv.name = @p_name
                ) THEN 1 ELSE 0 END,
                NULL,
                NULL,
                NULL;
        END
    ELSE IF @p_action = 50 /* CheckpointSlotAction.Delete */
        BEGIN
            DELETE FROM acta.checkpoints
            WHERE
                job_id = @p_job_id
                AND kind_code = @p_kind_code
                AND name = @p_name;

            INSERT INTO @row (found, value_format_id, value, version)
            VALUES (CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END, NULL, NULL, NULL);
        END
    ELSE
        BEGIN
            THROW 50002, 'checkpoint_slot received an unknown action.', 1;
        END

    SELECT
        found,
        value_format_id,
        value,
        version
    FROM @row;
END;
GO
CREATE OR ALTER PROCEDURE acta.get_child_job_ids
    @p_parent_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT j.id AS job_id
    FROM acta.jobs j
    WHERE j.parent_id = @p_parent_id;
END;
GO
CREATE OR ALTER PROCEDURE acta.get_stale_child_latches
    @p_namespace_id SMALLINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        js.job_id AS parent_job_id,
        TRY_CAST(SUBSTRING(js.name, 11, 20) AS BIGINT) AS child_job_id,
        cr.status_code AS child_status
    FROM acta.checkpoints js
    INNER JOIN acta.jobs p ON p.id = js.job_id AND p.namespace_id = @p_namespace_id
    LEFT JOIN acta.jobs c
        ON c.id = TRY_CAST(SUBSTRING(js.name, 11, 20) AS BIGINT)
    LEFT JOIN acta.runtimes cr ON cr.job_id = c.id
    WHERE
        js.kind_code = 50 /* JobCheckpointKindCode.ChildLatch */
        AND js.name LIKE 'sys.child.%'
        AND TRY_CAST(SUBSTRING(js.name, 11, 20) AS BIGINT) IS NOT NULL
        AND js.status_code = 10 /* JobCheckpointStatusCode.Pending */
        AND (c.id IS NULL OR cr.status_code IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */));
END;
GO
CREATE OR ALTER PROCEDURE acta.claim_batch
    @p_namespace_id SMALLINT,
    @p_leased_by_worker_id INT,
    @p_claim_limit INT,
    @p_lease_ttl_seconds INT,
    @p_start_executing BIT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @lease_expires DATETIME2(3) = DATEADD(SECOND, @p_lease_ttl_seconds, @now);
    /* Dueness compares at the column's DATETIME2(3) precision: enqueue rounds next_run_at_utc up to
       0.5 ms into the future, so a full-precision @now can transiently see a just-enqueued row as
       not yet due. Rounding is monotonic, so the same-precision comparison never can. */
    DECLARE @due_now DATETIME2(3) = @now;

    DECLARE
        @claimed TABLE
        (
            id BIGINT NOT NULL PRIMARY KEY,
            job_ref UNIQUEIDENTIFIER NOT NULL,
            namespace_id SMALLINT NOT NULL,
            lineage_root_id BIGINT NULL,
            definition_id INT NOT NULL,
            tenant_id INT NULL,
            execution_number INT NOT NULL,
            deduplication_key VARCHAR(128) NULL,
            correlation_key VARCHAR(64) NULL,
            exclusive_key VARCHAR(128) NULL,
            input_format_id TINYINT NOT NULL,
            input VARBINARY(MAX) NULL,
            next_run_at_utc DATETIME2(3) NULL,
            created_at_utc DATETIME2(3) NOT NULL,
            audit_level_code TINYINT NOT NULL,
            failure_count SMALLINT NOT NULL,
            version INT NOT NULL
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        WITH candidates AS (
            /* Pure ready-index scan: the hot predicate and ORDER run on ix_runtimes_claim_ready
               alone via the denormalized namespace. Exclusive-key admission is executor-owned
               (lock store), taken after the start CAS, so no jobs join here. */
            SELECT TOP (@p_claim_limit) r.job_id AS id
            FROM acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK, READCOMMITTEDLOCK)
            WHERE
                r.namespace_id = @p_namespace_id
                AND r.status_code = 10 /* JobStatusCode.Ready */
                AND (r.next_run_at_utc IS NULL OR r.next_run_at_utc <= @due_now)
            ORDER BY
                r.priority_code DESC,
                r.next_run_at_utc ASC,
                r.job_id ASC
        )

        UPDATE r
        SET
            status_code = CASE WHEN @p_start_executing = 1 THEN 50 /* JobStatusCode.Executing */ ELSE 40 /* JobStatusCode.Dispatched */ END,
            execution_number = r.execution_number + 1,
            leased_by_worker_id = @p_leased_by_worker_id,
            lease_expires_at_utc = @lease_expires,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id,
            j.job_ref,
            j.namespace_id,
            j.lineage_root_id,
            j.definition_id,
            j.tenant_id,
            INSERTED.execution_number,
            j.deduplication_key,
            j.correlation_key,
            j.exclusive_key,
            j.input_format_id,
            j.input,
            INSERTED.next_run_at_utc,
            j.created_at_utc,
            j.audit_level_code,
            INSERTED.failure_count,
            INSERTED.version
        INTO
            @claimed (
                id, job_ref, namespace_id, lineage_root_id, definition_id, tenant_id, execution_number,
                deduplication_key, correlation_key, exclusive_key,
                input_format_id, input, next_run_at_utc, created_at_utc,
                audit_level_code, failure_count, version
            )
        FROM acta.runtimes r
        INNER JOIN candidates c ON c.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        IF @p_start_executing = 1
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                SELECT
                    40 /* EventCode.JobExecutionStarted */,
                    @now,
                    c.namespace_id,
                    70 /* ActorCode.Worker */,
                    NULL,
                    c.id,
                    c.job_ref,
                    c.execution_number,
                    COALESCE(c.lineage_root_id, c.id),
                    c.definition_id,
                    c.tenant_id,
                    @p_leased_by_worker_id,
                    10 /* JobStatusCode.Ready */,
                    50 /* JobStatusCode.Executing */,
                    50 /* ExecutionStatusCode.Executing */,
                    NULL,
                    NULL,
                    NULL
                FROM @claimed c
                WHERE c.audit_level_code = 20 /* JobAuditLevelCode.Audit */;
            END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    IF EXISTS (SELECT 1 FROM @claimed)
        BEGIN
            SELECT
                id,
                namespace_id,
                definition_id,
                execution_number,
                deduplication_key,
                correlation_key,
                exclusive_key,
                input_format_id,
                input,
                next_run_at_utc,
                @lease_expires AS lease_expires_at_utc,
                created_at_utc,
                failure_count,
                version,
                job_ref,
                tenant_id,
                CAST(NULL AS DATETIME2(7)) AS db_now,
                CAST(NULL AS DATETIME2(3)) AS next_ready_at_utc
            FROM @claimed
            ORDER BY id;
        END
    ELSE
        BEGIN
            SELECT
                CAST(NULL AS BIGINT) AS id,
                CAST(NULL AS SMALLINT) AS namespace_id,
                CAST(NULL AS INT) AS definition_id,
                CAST(NULL AS INT) AS execution_number,
                CAST(NULL AS VARCHAR(128)) AS deduplication_key,
                CAST(NULL AS VARCHAR(64)) AS correlation_key,
                CAST(NULL AS VARCHAR(128)) AS exclusive_key,
                CAST(NULL AS TINYINT) AS input_format_id,
                CAST(NULL AS VARBINARY(MAX)) AS input,
                CAST(NULL AS DATETIME2(3)) AS next_run_at_utc,
                CAST(NULL AS DATETIME2(3)) AS lease_expires_at_utc,
                CAST(NULL AS DATETIME2(3)) AS created_at_utc,
                CAST(NULL AS SMALLINT) AS failure_count,
                CAST(NULL AS INT) AS version,
                CAST(NULL AS UNIQUEIDENTIFIER) AS job_ref,
                CAST(NULL AS INT) AS tenant_id,
                @now AS db_now,
                (
                    SELECT MIN(COALESCE(r.next_run_at_utc, @now))
                    FROM acta.runtimes r
                    WHERE
                        r.namespace_id = @p_namespace_id
                        AND r.status_code = 10 /* JobStatusCode.Ready */
                ) AS next_ready_at_utc;
        END
END;
GO
CREATE OR ALTER PROCEDURE acta.claim_one
    @p_namespace_id SMALLINT,
    @p_leased_by_worker_id INT,
    @p_lease_ttl_seconds INT,
    @p_id BIGINT,
    @p_start_executing BIT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @lease_expires DATETIME2(3) = DATEADD(SECOND, @p_lease_ttl_seconds, @now);
    /* Dueness compares at the column's DATETIME2(3) precision: enqueue rounds next_run_at_utc up to
       0.5 ms into the future, so a full-precision @now can transiently see a just-enqueued row as
       not yet due. Rounding is monotonic, so the same-precision comparison never can. */
    DECLARE @due_now DATETIME2(3) = @now;

    DECLARE
        @claimed TABLE
        (
            id BIGINT NOT NULL PRIMARY KEY,
            job_ref UNIQUEIDENTIFIER NOT NULL,
            namespace_id SMALLINT NOT NULL,
            lineage_root_id BIGINT NULL,
            definition_id INT NOT NULL,
            tenant_id INT NULL,
            execution_number INT NOT NULL,
            deduplication_key VARCHAR(128) NULL,
            correlation_key VARCHAR(64) NULL,
            exclusive_key VARCHAR(128) NULL,
            input_format_id TINYINT NOT NULL,
            input VARBINARY(MAX) NULL,
            next_run_at_utc DATETIME2(3) NULL,
            created_at_utc DATETIME2(3) NOT NULL,
            audit_level_code TINYINT NOT NULL,
            failure_count SMALLINT NOT NULL,
            version INT NOT NULL
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        WITH candidates AS (
            SELECT r.job_id AS id
            FROM acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK, READCOMMITTEDLOCK)
            WHERE
                r.job_id = @p_id
                AND r.namespace_id = @p_namespace_id
                AND r.status_code = 10 /* JobStatusCode.Ready */
                AND (r.next_run_at_utc IS NULL OR r.next_run_at_utc <= @due_now)
        )

        UPDATE r
        SET
            status_code = CASE WHEN @p_start_executing = 1 THEN 50 /* JobStatusCode.Executing */ ELSE 40 /* JobStatusCode.Dispatched */ END,
            execution_number = r.execution_number + 1,
            leased_by_worker_id = @p_leased_by_worker_id,
            lease_expires_at_utc = @lease_expires,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id, j.job_ref, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id,
            INSERTED.execution_number, j.deduplication_key, j.correlation_key, j.exclusive_key,
            j.input_format_id, j.input, INSERTED.next_run_at_utc, j.created_at_utc, j.audit_level_code,
            INSERTED.failure_count, INSERTED.version
        INTO
            @claimed (
                id, job_ref, namespace_id, lineage_root_id, definition_id, tenant_id, execution_number,
                deduplication_key, correlation_key, exclusive_key,
                input_format_id, input, next_run_at_utc, created_at_utc,
                audit_level_code, failure_count, version
            )
        FROM acta.runtimes r
        INNER JOIN candidates c ON c.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        IF @p_start_executing = 1
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id, actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id, worker_id,
                    from_status_code, to_status_code, execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                SELECT
                    40 /* EventCode.JobExecutionStarted */,
                    @now,
                    c.namespace_id,
                    70 /* ActorCode.Worker */,
                    NULL,
                    c.id,
                    c.job_ref,
                    c.execution_number,
                    COALESCE(c.lineage_root_id, c.id),
                    c.definition_id,
                    c.tenant_id,
                    @p_leased_by_worker_id,
                    10 /* JobStatusCode.Ready */,
                    50 /* JobStatusCode.Executing */,
                    50 /* ExecutionStatusCode.Executing */,
                    NULL,
                    NULL,
                    NULL
                FROM @claimed c
                WHERE c.audit_level_code = 20 /* JobAuditLevelCode.Audit */;
            END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        id,
        namespace_id,
        definition_id,
        execution_number,
        deduplication_key,
        correlation_key,
        exclusive_key,
        input_format_id,
        input,
        next_run_at_utc,
        @lease_expires AS lease_expires_at_utc,
        created_at_utc,
        failure_count,
        version,
        job_ref,
        tenant_id,
        CAST(NULL AS DATETIME2(7)) AS db_now,
        CAST(NULL AS DATETIME2(3)) AS next_ready_at_utc
    FROM @claimed;
END;
GO
CREATE OR ALTER PROCEDURE acta.complete_execution
    @p_id BIGINT,
    @p_leased_by_worker_id INT,
    @p_execution_number INT,
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512),
    @p_result_format_id TINYINT,
    @p_result VARBINARY(MAX),
    @p_execution_succeeded BIT,
    @p_duration_ms INT,
    @p_final_status TINYINT = NULL,
    @p_job_next_run_at_utc DATETIME2(3) = NULL,
    @p_failure_count SMALLINT = NULL,
    @p_recurring_result_cap INT = 0,
    @p_reschedule_status_code TINYINT = NULL,
    @p_reschedule_delay_seconds INT = NULL,
    @p_reschedule_resume_at_utc DATETIME2(3) = NULL,
    @p_wait_signal_name NVARCHAR(128) = NULL,
    @p_handler_status_code TINYINT = NULL,
    @p_retention_seconds INT = NULL,
    @p_schedule_advances acta.job_schedule_advance_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @action TINYINT;
    DECLARE @recurring BIT = CASE WHEN @p_final_status IS NOT NULL THEN 1 ELSE 0 END;

    DECLARE @rearm BIT = CASE WHEN @p_reschedule_status_code IS NOT NULL THEN 1 ELSE 0 END;

    DECLARE @signal_suspend BIT = CASE WHEN @rearm = 1 AND @p_wait_signal_name IS NOT NULL THEN 1 ELSE 0 END;

    DECLARE @handler BIT = CASE WHEN @p_handler_status_code IS NOT NULL THEN 1 ELSE 0 END;
    DECLARE @sig_state TINYINT = NULL;
    DECLARE @to_status TINYINT;
    DECLARE @final_status TINYINT;
    DECLARE @final_next_run DATETIME2(3);
    DECLARE @parent_id BIGINT;
    DECLARE @parent_released TINYINT = 0;

    DECLARE @matched BIT = 0;
    DECLARE
        @c_ref UNIQUEIDENTIFIER, @c_ns SMALLINT, @c_lineage BIGINT, @c_def INT, @c_tenant INT, @c_exec INT,
        @c_audit TINYINT,
        @c_next_existing DATETIME2(3), @c_retention_existing DATETIME2(3), @c_failcount_existing SMALLINT;
    DECLARE @c_next DATETIME2(3), @c_retention DATETIME2(3), @c_failcount SMALLINT;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @signal_suspend = 1
            BEGIN
                SELECT @sig_state = status_code
                FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
                WHERE
                    job_id = @p_id
                    AND kind_code IN (20 /* JobCheckpointKindCode.Signal */, 50 /* JobCheckpointKindCode.ChildLatch */)
                    AND name = @p_wait_signal_name;
            END

        SET @to_status = CASE
            WHEN @signal_suspend = 1 AND @sig_state = 20 /* JobCheckpointStatusCode.Set */ THEN 10 /* JobStatusCode.Ready */
            WHEN @signal_suspend = 1 THEN 20 /* JobStatusCode.Suspended */
            WHEN @rearm = 1 THEN 10 /* JobStatusCode.Ready */
            WHEN @handler = 1 THEN @p_handler_status_code
            WHEN @recurring = 1 THEN @p_final_status
            WHEN @p_execution_succeeded = 1 THEN 100 /* JobStatusCode.Succeeded */
            ELSE 200 /* JobStatusCode.Failed */
        END;

        SELECT
            @matched = 1,
            @c_ref = j.job_ref,
            @c_ns = j.namespace_id,
            @c_lineage = j.lineage_root_id,
            @c_def = j.definition_id,
            @c_tenant = j.tenant_id,
            @c_exec = r.execution_number,
            @c_audit = j.audit_level_code,
            @parent_id = j.parent_id,
            @c_next_existing = r.next_run_at_utc,
            @c_retention_existing = r.retention_until_utc,
            @c_failcount_existing = r.failure_count
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE
            r.job_id = @p_id
            AND r.execution_number = @p_execution_number
            AND r.status_code = 50 /* JobStatusCode.Executing */
            AND r.leased_by_worker_id = @p_leased_by_worker_id;

        IF @matched = 1
            BEGIN
                SET @action = 1 /* CompleteExecutionAction.Completed */;

                SET @c_next = CASE
                    WHEN @signal_suspend = 1 AND @sig_state = 20 /* JobCheckpointStatusCode.Set */ THEN @now
                    WHEN @signal_suspend = 1 THEN NULL
                    WHEN @rearm = 1 THEN COALESCE(@p_reschedule_resume_at_utc, DATEADD(SECOND, @p_reschedule_delay_seconds, @now))
                    WHEN @handler = 1 THEN NULL
                    WHEN @recurring = 1 THEN @p_job_next_run_at_utc
                    ELSE @c_next_existing
                END;

                SET @c_retention = CASE
                    WHEN
                        @to_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                        AND @p_retention_seconds IS NOT NULL
                        THEN DATEADD(SECOND, @p_retention_seconds, @now)
                    ELSE @c_retention_existing
                END;

                SET @c_failcount = COALESCE(@p_failure_count, @c_failcount_existing);

                UPDATE acta.runtimes
                SET
                    status_code = @to_status,
                    next_run_at_utc = @c_next,
                    failure_count = @c_failcount,
                    leased_by_worker_id = NULL,
                    lease_expires_at_utc = NULL,
                    retention_until_utc = @c_retention,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_id;

                SET @final_status = @to_status;
                SET @final_next_run = @c_next;

                IF @p_result_format_id <> 0 /* JobPayloadFormat.None */
                    BEGIN
                        INSERT INTO acta.results (
                            job_id, execution_number,
                            result_format_id, result,
                            created_at_utc
                        )
                        VALUES (@p_id, @c_exec, @p_result_format_id, @p_result, @now);
                    END

                IF @recurring = 1
                    BEGIN
                        INSERT INTO acta.events (
                            event_code, created_at_utc, namespace_id,
                            actor_code, actor_key,
                            job_id, job_ref, execution_number,
                            lineage_root_id, definition_id, tenant_id,
                            worker_id,
                            from_status_code, to_status_code,
                            execution_status_code, duration_ms,
                            reason_code, reason_message
                        )
                        SELECT
                            102 /* EventCode.SchedulePauseExpired */,
                            @now,
                            @c_ns,
                            10 /* ActorCode.Sys */,
                            NULL,
                            @p_id,
                            @c_ref,
                            @c_exec,
                            COALESCE(@c_lineage, @p_id),
                            @c_def,
                            @c_tenant,
                            NULL,
                            NULL,
                            NULL,
                            NULL,
                            NULL,
                            NULL,
                            js.name
                        FROM acta.schedules js
                        INNER JOIN @p_schedule_advances adv ON adv.schedule_id = js.id
                        WHERE
                            @c_audit = 20 /* JobAuditLevelCode.Audit */
                            AND js.status_code = 30 /* ScheduleStatusCode.Paused */
                            AND js.paused_until_utc IS NOT NULL
                            AND js.paused_until_utc <= @now;

                        UPDATE js
                        SET
                            js.next_run_at_utc = adv.next_run_at_utc,
                            js.last_occurrence_at_utc = js.next_run_at_utc,
                            js.status_code = 10 /* ScheduleStatusCode.Active */,
                            js.paused_until_utc = NULL,
                            js.modified_at_utc = @now,
                            js.version = js.version + 1
                        -- An operator pause inside the fire window wins: the advance was planned before
                        -- the pause existed. Only an elapsed TIMED pause auto-resumes here, and the audit
                        -- insert above shares this predicate so the two cannot disagree.
                        FROM acta.schedules js
                        INNER JOIN @p_schedule_advances adv ON adv.schedule_id = js.id
                        WHERE
                            js.status_code <> 30 /* ScheduleStatusCode.Paused */
                            OR (js.paused_until_utc IS NOT NULL AND js.paused_until_utc <= @now);

                        IF @p_recurring_result_cap > 0
                            BEGIN
                                DELETE r
                                FROM acta.results r
                                WHERE
                                    r.job_id = @p_id
                                    AND r.execution_number NOT IN (
                                        SELECT TOP (@p_recurring_result_cap) execution_number
                                        FROM acta.results
                                        WHERE job_id = @p_id
                                        ORDER BY execution_number DESC
                                    );
                            END
                    END

                IF
                    @c_audit = 20 /* JobAuditLevelCode.Audit */
                    OR (
                        @c_audit = 10 /* JobAuditLevelCode.Failures */ AND @p_execution_succeeded = 0 AND @rearm = 0
                        AND NOT (
                            @handler = 1 AND @p_handler_status_code IN (220 /* JobStatusCode.Cancelled */, 30 /* JobStatusCode.Paused */)
                        )
                    )
                    BEGIN
                        INSERT INTO acta.events (
                            event_code, created_at_utc, namespace_id,
                            actor_code, actor_key,
                            job_id, job_ref, execution_number,
                            lineage_root_id, definition_id, tenant_id,
                            worker_id,
                            from_status_code, to_status_code,
                            execution_status_code, duration_ms,
                            reason_code, reason_message
                        )
                        VALUES (
                            41 /* EventCode.JobExecutionFinished */, @now, @c_ns,
                            70 /* ActorCode.Worker */, NULL,
                            @p_id, @c_ref, @c_exec,
                            COALESCE(@c_lineage, @p_id), @c_def, @c_tenant,
                            @p_leased_by_worker_id,
                            50 /* JobStatusCode.Executing */, @to_status,
                            CASE
                                WHEN @rearm = 1 THEN @p_reschedule_status_code
                                WHEN
                                    @handler = 1 AND @p_handler_status_code = 220
                                    /* JobStatusCode.Cancelled */ THEN 220 /* ExecutionStatusCode.Cancelled */
                                WHEN
                                    @handler = 1 AND @p_handler_status_code = 30
                                    /* JobStatusCode.Paused */ THEN 152 /* ExecutionStatusCode.Paused */
                                WHEN @p_execution_succeeded = 1 THEN 100 /* ExecutionStatusCode.Succeeded */
                                ELSE 200 /* ExecutionStatusCode.Failed */
                            END,
                            @p_duration_ms,
                            @p_reason_code,
                            @p_reason_message
                        );
                    END

                IF
                    @recurring = 1 AND @c_audit = 20 /* JobAuditLevelCode.Audit */
                    AND @p_final_status IN (10 /* JobStatusCode.Ready */, 30 /* JobStatusCode.Paused */)
                    BEGIN
                        INSERT INTO acta.events (
                            event_code, created_at_utc, namespace_id,
                            actor_code, actor_key,
                            job_id, job_ref, execution_number,
                            lineage_root_id, definition_id, tenant_id,
                            worker_id,
                            from_status_code, to_status_code,
                            execution_status_code, duration_ms,
                            reason_code, reason_message
                        )
                        VALUES (
                            CASE
                                WHEN @p_final_status = 10 /* JobStatusCode.Ready */ THEN 50 /* EventCode.JobRecurringRolledOver */
                                ELSE 71 /* EventCode.JobPaused */
                            END,
                            @now, @c_ns,
                            70 /* ActorCode.Worker */, NULL,
                            @p_id, @c_ref, @c_exec,
                            COALESCE(@c_lineage, @p_id), @c_def, @c_tenant,
                            @p_leased_by_worker_id,
                            50 /* JobStatusCode.Executing */, @to_status,
                            NULL, NULL,
                            @p_reason_code, @p_reason_message
                        );
                    END

                IF
                    @rearm = 1 AND @c_audit = 20 /* JobAuditLevelCode.Audit */
                    AND NOT (@signal_suspend = 1 AND @to_status = 10 /* JobStatusCode.Ready */)
                    BEGIN
                        INSERT INTO acta.events (
                            event_code, created_at_utc, namespace_id,
                            actor_code, actor_key,
                            job_id, job_ref, execution_number,
                            lineage_root_id, definition_id, tenant_id,
                            worker_id,
                            from_status_code, to_status_code,
                            execution_status_code, duration_ms,
                            reason_code, reason_message
                        )
                        VALUES (
                            CASE
                                WHEN
                                    @p_reschedule_status_code = 151
                                    /* ExecutionStatusCode.Suspended */ THEN 60 /* EventCode.JobSuspended */
                                ELSE 61 /* EventCode.JobRescheduled */
                            END,
                            @now, @c_ns,
                            70 /* ActorCode.Worker */, NULL,
                            @p_id, @c_ref, @c_exec,
                            COALESCE(@c_lineage, @p_id), @c_def, @c_tenant,
                            @p_leased_by_worker_id,
                            50 /* JobStatusCode.Executing */, @to_status,
                            NULL, NULL,
                            @p_reason_code, @p_reason_message
                        );
                    END

                IF
                    @handler = 1 AND @c_audit = 20 /* JobAuditLevelCode.Audit */
                    AND @p_handler_status_code IN (220 /* JobStatusCode.Cancelled */, 30 /* JobStatusCode.Paused */)
                    BEGIN
                        INSERT INTO acta.events (
                            event_code, created_at_utc, namespace_id,
                            actor_code, actor_key,
                            job_id, job_ref, execution_number,
                            lineage_root_id, definition_id, tenant_id,
                            worker_id,
                            from_status_code, to_status_code,
                            execution_status_code, duration_ms,
                            reason_code, reason_message
                        )
                        VALUES (
                            CASE
                                WHEN @p_handler_status_code = 220 /* JobStatusCode.Cancelled */ THEN 70 /* EventCode.JobCancelled */
                                ELSE 71 /* EventCode.JobPaused */
                            END,
                            @now, @c_ns,
                            70 /* ActorCode.Worker */, NULL,
                            @p_id, @c_ref, @c_exec,
                            COALESCE(@c_lineage, @p_id), @c_def, @c_tenant,
                            @p_leased_by_worker_id,
                            50 /* JobStatusCode.Executing */, @to_status,
                            NULL, NULL,
                            @p_reason_code, @p_reason_message
                        );
                    END

                IF
                    @to_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                    AND @parent_id IS NOT NULL
                    BEGIN
                        DECLARE @sig VARCHAR(128) = 'sys.child.' + CAST(@p_id AS VARCHAR(20));
                        DECLARE @psig TINYINT, @pstatus TINYINT, @pns SMALLINT, @plineage BIGINT;
                        DECLARE @pdef INT, @ptenant INT, @pexec INT, @paudit TINYINT;
                        DECLARE @parent_ref UNIQUEIDENTIFIER;

                        SELECT @psig = status_code
                        FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
                        WHERE job_id = @parent_id AND kind_code = 50 /* JobCheckpointKindCode.ChildLatch */ AND name = @sig;

                        SELECT
                            @pstatus = pr.status_code,
                            @pns = j.namespace_id,
                            @plineage = j.lineage_root_id,
                            @pdef = j.definition_id,
                            @ptenant = j.tenant_id,
                            @pexec = pr.execution_number,
                            @paudit = j.audit_level_code,
                            @parent_ref = j.job_ref
                        FROM acta.runtimes pr WITH (UPDLOCK, ROWLOCK)
                        INNER JOIN acta.jobs j ON j.id = pr.job_id
                        WHERE pr.job_id = @parent_id;

                        IF
                            @pstatus IS NOT NULL
                            AND @pstatus NOT IN (
                                100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */
                            )
                            BEGIN
                                DECLARE
                                    @envelope NVARCHAR(MAX)
                                    = N'{"childJobId":' + CAST(@p_id AS NVARCHAR(20))
                                    + N',"status":' + CAST(@to_status AS NVARCHAR(3))
                                    + N'}';
                                DECLARE
                                    @envelope_bytes VARBINARY(MAX)
                                    = CAST(CAST(@envelope AS VARCHAR(MAX)) COLLATE latin1_general_100_bin2_utf8 AS VARBINARY(MAX));

                                IF @psig IS NULL
                                    BEGIN
                                        INSERT INTO acta.checkpoints (
                                            job_id, kind_code, name, status_code, value_format_id, value,
                                            created_at_utc, modified_at_utc, version
                                        )
                                        VALUES (
                                            @parent_id,
                                            50 /* JobCheckpointKindCode.ChildLatch */,
                                            @sig,
                                            20 /* JobCheckpointStatusCode.Set */,
                                            1 /* JobPayloadFormat.Json */,
                                            @envelope_bytes,
                                            @now,
                                            @now,
                                            0
                                        );
                                    END
                                ELSE
                                    BEGIN
                                        UPDATE acta.checkpoints
                                        SET
                                            status_code = 20 /* JobCheckpointStatusCode.Set */,
                                            value_format_id = 1 /* JobPayloadFormat.Json */,
                                            value = @envelope_bytes,
                                            modified_at_utc = @now,
                                            version = version + 1
                                        WHERE job_id = @parent_id AND kind_code = 50 /* JobCheckpointKindCode.ChildLatch */ AND name = @sig;
                                    END

                                IF @paudit = 20 /* JobAuditLevelCode.Audit */
                                    BEGIN
                                        INSERT INTO acta.events (
                                            event_code, created_at_utc, namespace_id,
                                            actor_code, actor_key,
                                            job_id, job_ref, execution_number,
                                            lineage_root_id, definition_id, tenant_id,
                                            worker_id,
                                            from_status_code, to_status_code,
                                            execution_status_code, duration_ms,
                                            reason_code, reason_message
                                        )
                                        VALUES (
                                            80 /* EventCode.JobSignalRaised */, @now, @pns,
                                            10 /* ActorCode.Sys */, NULL,
                                            @parent_id, @parent_ref, @pexec,
                                            COALESCE(@plineage, @parent_id), @pdef, @ptenant,
                                            NULL,
                                            @pstatus, @pstatus,
                                            NULL, NULL,
                                            @p_reason_code, @p_reason_message
                                        );
                                    END

                                IF @pstatus = 20 /* JobStatusCode.Suspended */
                                    BEGIN
                                        UPDATE acta.runtimes
                                        SET
                                            status_code = 10 /* JobStatusCode.Ready */,
                                            next_run_at_utc = @now,
                                            modified_at_utc = @now,
                                            version = version + 1
                                        WHERE job_id = @parent_id;

                                        IF @paudit = 20 /* JobAuditLevelCode.Audit */
                                            BEGIN
                                                INSERT INTO acta.events (
                                                    event_code, created_at_utc, namespace_id,
                                                    actor_code, actor_key,
                                                    job_id, job_ref, execution_number,
                                                    lineage_root_id, definition_id, tenant_id,
                                                    worker_id,
                                                    from_status_code, to_status_code,
                                                    execution_status_code, duration_ms,
                                                    reason_code, reason_message
                                                )
                                                VALUES (
                                                    72 /* EventCode.JobResumed */, @now, @pns,
                                                    10 /* ActorCode.Sys */, NULL,
                                                    @parent_id, @parent_ref, @pexec,
                                                    COALESCE(@plineage, @parent_id), @pdef, @ptenant,
                                                    NULL,
                                                    20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */,
                                                    NULL, NULL,
                                                    60 /* JobEventReasonCode.JobSignalReleased */, NULL
                                                );
                                            END

                                        SET @parent_released = 1;
                                    END
                            END
                    END

            END
        ELSE
            BEGIN
                DECLARE @curWorker INT, @curStatus TINYINT;
                SELECT
                    @curStatus = status_code,
                    @final_next_run = next_run_at_utc,
                    @curWorker = leased_by_worker_id
                FROM acta.runtimes
                WHERE job_id = @p_id;

                SET @final_status = @curStatus;
                SET @action = CASE
                    WHEN
                        @curStatus IS NULL
                        OR @curStatus IN (
                            100 /* JobStatusCode.Succeeded */,
                            200 /* JobStatusCode.Failed */,
                            220 /* JobStatusCode.Cancelled */
                        )
                        THEN 3 /* CompleteExecutionAction.AlreadyTerminal */
                    WHEN @curWorker <> @p_leased_by_worker_id OR @curWorker IS NULL
                        THEN 2 /* CompleteExecutionAction.NotOwner */
                    ELSE 3 /* CompleteExecutionAction.AlreadyTerminal */
                END;
            END

        COMMIT TRANSACTION;

        SELECT
            @action,
            @final_status,
            @final_next_run,
            @now,
            @parent_released;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.complete_executions_batch
    @p_batch acta.complete_executions_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    DECLARE @updated TABLE (
        ordinal INT NOT NULL PRIMARY KEY,
        job_id BIGINT NOT NULL,
        execution_number INT NOT NULL,
        job_ref UNIQUEIDENTIFIER NOT NULL,
        namespace_id SMALLINT NOT NULL,
        lineage_root_id BIGINT NULL,
        definition_id INT NOT NULL,
        tenant_id INT NULL,
        audit_level_code TINYINT NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE r
        SET
            status_code = CASE WHEN b.succeeded = 1 THEN 100 /* JobStatusCode.Succeeded */ ELSE 200 /* JobStatusCode.Failed */ END,
            failure_count = COALESCE(b.failure_count, r.failure_count),
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = CASE
                WHEN b.retention_seconds IS NOT NULL
                    THEN DATEADD(SECOND, b.retention_seconds, @now)
                ELSE r.retention_until_utc
            END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            b.ordinal, INSERTED.job_id, INSERTED.execution_number, j.job_ref, j.namespace_id,
            j.lineage_root_id, j.definition_id, j.tenant_id, j.audit_level_code
        INTO @updated
        FROM acta.runtimes r
        INNER JOIN acta.jobs j ON j.id = r.job_id
        INNER JOIN @p_batch b
            ON
                b.job_id = r.job_id
                AND b.execution_number = r.execution_number
        WHERE
            r.status_code = 50 /* JobStatusCode.Executing */
            AND j.parent_id IS NULL
            AND r.leased_by_worker_id = b.worker_id;

        INSERT INTO acta.results (job_id, execution_number, result_format_id, result, created_at_utc)
        SELECT
            u.job_id,
            u.execution_number,
            b.result_format_id,
            b.result,
            @now
        FROM @updated u
        INNER JOIN @p_batch b ON b.ordinal = u.ordinal
        WHERE b.result_format_id <> 0 /* JobPayloadFormat.None */;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id,
            worker_id, from_status_code, to_status_code, execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            41 /* EventCode.JobExecutionFinished */,
            @now,
            u.namespace_id,
            70 /* ActorCode.Worker */,
            NULL,
            u.job_id,
            u.job_ref,
            u.execution_number,
            COALESCE(u.lineage_root_id, u.job_id),
            u.definition_id,
            u.tenant_id,
            b.worker_id,
            50 /* JobStatusCode.Executing */,
            CASE WHEN b.succeeded = 1 THEN 100 /* JobStatusCode.Succeeded */ ELSE 200 /* JobStatusCode.Failed */ END,
            CASE WHEN b.succeeded = 1 THEN 100 /* ExecutionStatusCode.Succeeded */ ELSE 200 /* ExecutionStatusCode.Failed */ END,
            b.duration_ms,
            b.reason_code,
            b.reason_message
        FROM @updated u
        INNER JOIN @p_batch b ON b.ordinal = u.ordinal
        WHERE
            u.audit_level_code = 20 /* JobAuditLevelCode.Audit */
            OR (u.audit_level_code = 10 /* JobAuditLevelCode.Failures */ AND b.succeeded = 0);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        b.ordinal,
        CAST(CASE WHEN u.ordinal IS NOT NULL THEN 1 ELSE 0 END AS SMALLINT) AS finalized
    FROM @p_batch b
    LEFT JOIN @updated u ON u.ordinal = b.ordinal
    ORDER BY b.ordinal;
END;
GO
CREATE OR ALTER PROCEDURE acta.complete_step
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_succeeded BIT,
    @p_result_format_id TINYINT,
    @p_result VARBINARY(MAX),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512),
    @p_delay_seconds INT,
    @p_max_attempts SMALLINT,
    @p_retry_window_seconds INT,
    @p_version INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @attempt SMALLINT;
    DECLARE @created DATETIME2(3);
    DECLARE @next DATETIME2(3);
    DECLARE @outcome SMALLINT;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @attempt = attempt_number,
            @created = created_at_utc
        FROM acta.steps
        WHERE job_id = @p_job_id AND name = @p_name;

        IF @p_succeeded = 1
            BEGIN
                UPDATE acta.steps
                SET
                    status_code = 100 /* JobStepStatusCode.Succeeded */,
                    result_format_id = @p_result_format_id,
                    result = @p_result,
                    next_retry_at_utc = NULL,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND name = @p_name AND version = @p_version;

                IF @@ROWCOUNT = 0
                    SET @outcome = 4 /* CompleteStepOutcomeCode.StaleVersion */;
                ELSE
                    SET @outcome = 1 /* CompleteStepOutcomeCode.Succeeded */;
                SET @next = NULL;
            END
        ELSE
            BEGIN
                SET @next = DATEADD(SECOND, @p_delay_seconds, @now);

                IF
                    @attempt >= @p_max_attempts
                    OR (
                        @p_retry_window_seconds IS NOT NULL
                        AND @next > DATEADD(SECOND, @p_retry_window_seconds, @created)
                    )
                    BEGIN
                        UPDATE acta.steps
                        SET
                            status_code = 200 /* JobStepStatusCode.Exhausted */,
                            next_retry_at_utc = NULL,
                            reason_code = @p_reason_code,
                            reason_message = @p_reason_message,
                            modified_at_utc = @now,
                            version = version + 1
                        WHERE job_id = @p_job_id AND name = @p_name AND version = @p_version;

                        IF @@ROWCOUNT = 0
                            SET @outcome = 4 /* CompleteStepOutcomeCode.StaleVersion */;
                        ELSE
                            SET @outcome = 3 /* CompleteStepOutcomeCode.Exhausted */;
                        SET @next = NULL;
                    END
                ELSE
                    BEGIN
                        UPDATE acta.steps
                        SET
                            next_retry_at_utc = @next,
                            reason_code = @p_reason_code,
                            reason_message = @p_reason_message,
                            modified_at_utc = @now,
                            version = version + 1
                        WHERE job_id = @p_job_id AND name = @p_name AND version = @p_version;

                        IF @@ROWCOUNT = 0
                            BEGIN
                                SET @outcome = 4 /* CompleteStepOutcomeCode.StaleVersion */;
                                SET @next = NULL;
                            END
                        ELSE
                            SET @outcome = 2 /* CompleteStepOutcomeCode.RetryScheduled */;
                    END
            END

        COMMIT TRANSACTION;

        SELECT
            @outcome AS outcome_code,
            @next AS next_retry_at_utc;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.register_job_definitions
    @p_namespace_id SMALLINT,
    @p_manifest_generation DATETIME2(7),
    @p_definitions acta.job_definition_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @retired TABLE (id INT PRIMARY KEY);

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE jd SET
            status_code = 10 /* JobDefinitionStatusCode.Active */,
            input_type_name = src.input_type_name,
            output_type_name = src.output_type_name,
            input_format_id = src.input_format_id,
            input_format_name = src.input_format_name,
            output_format_id = src.output_format_id,
            output_format_name = src.output_format_name,
            priority_code = src.priority_code,
            max_attempts = src.max_attempts,
            backoff = src.backoff,
            execution_timeout_seconds = src.execution_timeout_seconds,
            deadline_seconds = src.deadline_seconds,
            deadline_behavior_code = src.deadline_behavior_code,
            retention_seconds = src.retention_seconds,
            audit_level_code = src.audit_level_code,
            alert_profile_code = src.alert_profile_code,
            tenant_requirement_code = src.tenant_requirement_code,
            alert_channel_name = src.alert_channel_name,
            runbook_url = src.runbook_url,
            display_name = src.display_name,
            description = src.description,
            definition_hash = src.definition_hash,
            manifest_generation_at_utc = @p_manifest_generation,
            modified_at_utc = @now,
            version = jd.version + 1
        FROM acta.definitions jd
        INNER JOIN @p_definitions src
            ON jd.namespace_id = @p_namespace_id AND jd.name = src.name
        WHERE
            @p_manifest_generation >= jd.manifest_generation_at_utc
            AND (
                jd.status_code <> 10 /* JobDefinitionStatusCode.Active */
                OR jd.definition_hash <> src.definition_hash
            );

        INSERT INTO acta.definitions (
            namespace_id, name, status_code,
            input_type_name, output_type_name,
            input_format_id, input_format_name,
            output_format_id, output_format_name,
            priority_code, max_attempts,
            backoff,
            execution_timeout_seconds,
            deadline_seconds,
            deadline_behavior_code,
            retention_seconds,
            audit_level_code, alert_profile_code,
            tenant_requirement_code,
            alert_channel_name, runbook_url,
            display_name, description,
            definition_hash, manifest_generation_at_utc,
            created_at_utc, modified_at_utc, version
        )
        SELECT
            @p_namespace_id,
            src.name,
            10 /* JobDefinitionStatusCode.Active */,
            src.input_type_name,
            src.output_type_name,
            src.input_format_id,
            src.input_format_name,
            src.output_format_id,
            src.output_format_name,
            src.priority_code,
            src.max_attempts,
            src.backoff,
            src.execution_timeout_seconds,
            src.deadline_seconds,
            src.deadline_behavior_code,
            src.retention_seconds,
            src.audit_level_code,
            src.alert_profile_code,
            src.tenant_requirement_code,
            src.alert_channel_name,
            src.runbook_url,
            src.display_name,
            src.description,
            src.definition_hash,
            @p_manifest_generation,
            @now,
            @now,
            0
        FROM @p_definitions src
        WHERE NOT EXISTS (
            SELECT 1 FROM acta.definitions jd
            WHERE jd.namespace_id = @p_namespace_id AND jd.name = src.name
        );

        -- Retire definitions absent from the manifest and capture the ids this call actually flipped,
        -- so the cancel-sweep can be scoped to exactly that set.
        UPDATE jd SET
            status_code = 240 /* JobDefinitionStatusCode.Retired */,
            modified_at_utc = @now,
            version = jd.version + 1
        OUTPUT INSERTED.id INTO @retired
        FROM acta.definitions jd WITH (INDEX (ux_definitions_namespace_name))
        WHERE
            jd.namespace_id = @p_namespace_id
            AND jd.status_code = 10 /* JobDefinitionStatusCode.Active */
            AND jd.manifest_generation_at_utc <= @p_manifest_generation
            AND NOT EXISTS (
                SELECT 1 FROM @p_definitions src
                WHERE src.name = jd.name
            );

        -- Retirement cancel-sweep: parked rows of definitions this call transitioned to retired.
        -- Definitions retired by an earlier call keep their parked jobs (a re-arm after retirement stays
        -- as the operator left it). In-flight Dispatched/Executing rows finish their attempt untouched.
        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor_key,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            70 /* EventCode.JobCancelled */,
            @now,
            j.namespace_id,
            10 /* ActorCode.Sys */,
            'sys:register-definitions',
            j.id,
            j.job_ref,
            r.execution_number,
            COALESCE(j.lineage_root_id, j.id),
            j.definition_id,
            j.tenant_id,
            NULL,
            r.status_code,
            220 /* JobStatusCode.Cancelled */,
            NULL,
            NULL,
            42 /* JobEventReasonCode.JobDefinitionRetired */,
            NULL
        FROM acta.jobs j
        INNER JOIN acta.runtimes r ON r.job_id = j.id
        INNER JOIN acta.definitions jd ON jd.id = j.definition_id
        WHERE
            jd.namespace_id = @p_namespace_id
            AND jd.id IN (SELECT id FROM @retired)
            AND j.audit_level_code = 20 /* JobAuditLevelCode.Audit */
            AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */, 30 /* JobStatusCode.Paused */);

        UPDATE r SET
            status_code = 220 /* JobStatusCode.Cancelled */,
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = DATEADD(SECOND, jd.retention_seconds_effective, @now),
            modified_at_utc = @now,
            version = r.version + 1
        FROM acta.runtimes r
        INNER JOIN acta.jobs j ON j.id = r.job_id
        INNER JOIN acta.definitions jd ON jd.id = j.definition_id
        WHERE
            jd.namespace_id = @p_namespace_id
            AND jd.id IN (SELECT id FROM @retired)
            AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */, 30 /* JobStatusCode.Paused */);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        jd.name,
        jd.id
    FROM @p_definitions src
    INNER JOIN acta.definitions jd
        ON jd.namespace_id = @p_namespace_id AND jd.name = src.name;
END;
GO
CREATE OR ALTER PROCEDURE acta.set_job_definition_overrides
    @p_id INT,
    @p_version INT,
    @p_priority_code_override TINYINT,
    @p_max_attempts_override SMALLINT,
    @p_backoff_override NVARCHAR(64),
    @p_execution_timeout_seconds_override INT,
    @p_deadline_seconds_override INT,
    @p_deadline_behavior_code_override TINYINT,
    @p_retention_seconds_override INT,
    @p_audit_level_code_override TINYINT,
    @p_alert_profile_code_override TINYINT,
    @p_alert_channel_name_override VARCHAR(128),
    @p_runbook_url_override VARCHAR(512),
    @p_display_name_override NVARCHAR(128),
    @p_description_override NVARCHAR(512),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @ns SMALLINT, @existing_version INT;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @ns = jd.namespace_id,
            @existing_version = jd.version
        FROM acta.definitions jd
        WHERE jd.id = @p_id;

        IF @ns IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT CAST(2 /* DefinitionOverrideAction.NotFound */ AS TINYINT) AS action;
                RETURN;
            END;

        IF @existing_version <> @p_version
            BEGIN
                COMMIT TRANSACTION;
                SELECT CAST(3 /* DefinitionOverrideAction.VersionConflict */ AS TINYINT) AS action;
                RETURN;
            END;

        UPDATE acta.definitions SET
            priority_code_override = @p_priority_code_override,
            max_attempts_override = @p_max_attempts_override,
            backoff_override = @p_backoff_override,
            execution_timeout_seconds_override = @p_execution_timeout_seconds_override,
            deadline_seconds_override = @p_deadline_seconds_override,
            deadline_behavior_code_override = @p_deadline_behavior_code_override,
            retention_seconds_override = @p_retention_seconds_override,
            audit_level_code_override = @p_audit_level_code_override,
            alert_profile_code_override = @p_alert_profile_code_override,
            alert_channel_name_override = @p_alert_channel_name_override,
            runbook_url_override = @p_runbook_url_override,
            display_name_override = @p_display_name_override,
            description_override = @p_description_override,
            modified_at_utc = @now,
            version = jd.version + 1
        FROM acta.definitions jd
        WHERE jd.id = @p_id;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor_key,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        VALUES (
            30 /* EventCode.JobDefinitionOverridesUpdated */, @now, @ns,
            @p_actor_code, @p_actor_key,
            NULL, NULL, NULL,
            NULL, @p_id,
            NULL,
            NULL, NULL,
            NULL, NULL,
            @p_reason_code, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT CAST(1 /* DefinitionOverrideAction.Applied */ AS TINYINT) AS action;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.cancel_job
    @p_id BIGINT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT,
        @lineage_root_id BIGINT, @definition_id INT, @tenant_id INT, @execution_number INT, @worker_id INT, @audit_level TINYINT,
        @parent_id BIGINT, @retention_seconds INT, @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @parent_id = j.parent_id,
            @job_ref = j.job_ref,
            @worker_id = r.leased_by_worker_id
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code,
                    CAST(NULL AS BIGINT) AS parent_id;
                RETURN;
            END;

        IF
            @from_status NOT IN (
                30 /* JobStatusCode.Paused */,
                20 /* JobStatusCode.Suspended */,
                10 /* JobStatusCode.Ready */,
                40 /* JobStatusCode.Dispatched */,
                50 /* JobStatusCode.Executing */
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code,
                    @parent_id AS parent_id;
                RETURN;
            END;

        SELECT @retention_seconds = jd.retention_seconds_effective
        FROM acta.definitions jd
        WHERE jd.id = @definition_id;

        UPDATE acta.runtimes
        SET
            status_code = 220 /* JobStatusCode.Cancelled */,
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = DATEADD(SECOND, @retention_seconds, @now),
            modified_at_utc = @now,
            version = version + 1
        WHERE job_id = @p_id;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                IF @from_status = 50 /* JobStatusCode.Executing */
                    BEGIN
                        INSERT INTO acta.events (
                            event_code, created_at_utc, namespace_id,
                            actor_code, actor_key,
                            job_id, job_ref, execution_number,
                            lineage_root_id, definition_id, tenant_id,
                            worker_id,
                            from_status_code, to_status_code,
                            execution_status_code, duration_ms,
                            reason_code, reason_message
                        )
                        VALUES (
                            41 /* EventCode.JobExecutionFinished */, @now, @namespace_id,
                            @p_actor_code, @p_actor_key,
                            @p_id, @job_ref, @execution_number,
                            COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                            @worker_id,
                            50 /* JobStatusCode.Executing */, 220 /* JobStatusCode.Cancelled */,
                            220 /* ExecutionStatusCode.Cancelled */, NULL,
                            @p_reason_code, @p_reason_message
                        );
                    END;

                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    70 /* EventCode.JobCancelled */, @now, @namespace_id,
                    @p_actor_code, @p_actor_key,
                    @p_id, @job_ref, @execution_number,
                    COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                    NULL,
                    @from_status, 220 /* JobStatusCode.Cancelled */,
                    NULL, NULL,
                    @p_reason_code, @p_reason_message
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            CAST(220 /* JobStatusCode.Cancelled */ AS TINYINT) AS status_code,
            @parent_id AS parent_id;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.enqueue_batch
    @p_batch acta.job_enqueue_batch READONLY,
    @p_tag_batch acta.job_enqueue_tag_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    -- Own a local transaction only when invoked outside one. Inside a caller's transaction (direct
    -- transactional enqueue) the entry count is > 0: run the work but neither commit nor roll back it;
    -- on error rethrow and let the caller roll back the whole transaction.
    DECLARE @entry_trancount INT = @@TRANCOUNT;

    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        DECLARE @resolved TABLE (
            ordinal INT PRIMARY KEY,
            ns_id SMALLINT NOT NULL,
            ns_status TINYINT NOT NULL,
            def_id INT NOT NULL,
            def_priority SMALLINT NOT NULL,
            def_audit_level TINYINT NOT NULL,
            def_status TINYINT NOT NULL,
            def_tenant_req TINYINT NOT NULL,
            tenant_id INT NULL
        );

        INSERT INTO @resolved (ordinal, ns_id, ns_status, def_id, def_priority, def_audit_level, def_status, def_tenant_req)
        SELECT
            b.ordinal,
            ns.id,
            ns.status_code,
            jd.id,
            jd.priority_code_effective,
            jd.audit_level_code_effective,
            jd.status_code,
            jd.tenant_requirement_code
        FROM @p_batch b
        INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
        INNER JOIN acta.definitions jd
            ON
                jd.namespace_id = ns.id
                AND jd.name = b.job_name;

        IF (SELECT COUNT(*) FROM @resolved) < (SELECT COUNT(*) FROM @p_batch)
            BEGIN
                DECLARE
                    @route_msg NVARCHAR(2048) = 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown'
                    + ' namespace or job. Has the owning worker run InitializeAsync yet?';
                THROW 50001, @route_msg, 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @resolved
                WHERE ns_status <> 10 /* NamespaceStatusCode.Active */
            )
            BEGIN
                THROW 50005, 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.', 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @resolved
                WHERE def_status <> 10 /* JobDefinitionStatusCode.Active */
            )
            BEGIN
                THROW 50003, 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.', 1;
            END;

        IF
            EXISTS (
                SELECT 1 FROM @p_batch
                WHERE tenant_key IS NOT NULL
            )
            BEGIN
                UPDATE r
                SET tenant_id = t.id
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                INNER JOIN acta.tenants t
                    ON
                        t.tenant_key = b.tenant_key
                        AND t.status_code = 10 /* TenantStatusCode.Active */
                WHERE b.tenant_key IS NOT NULL;

                IF
                    EXISTS (
                        SELECT 1 FROM @p_batch b
                        WHERE
                            b.tenant_key IS NOT NULL
                            AND NOT EXISTS (
                                SELECT 1 FROM acta.tenants t
                                WHERE t.tenant_key = b.tenant_key
                            )
                    )
                    BEGIN
                        THROW 50004, 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.', 1;
                    END;
                IF
                    EXISTS (
                        SELECT 1 FROM @p_batch b JOIN acta.tenants t ON t.tenant_key = b.tenant_key
                        WHERE b.tenant_key IS NOT NULL AND t.status_code <> 10 /* TenantStatusCode.Active */
                    )
                    BEGIN
                        THROW 50006, 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.', 1;
                    END;
            END;

        DECLARE @existing TABLE (
            ordinal INT PRIMARY KEY,
            id BIGINT NOT NULL,
            job_ref UNIQUEIDENTIFIER NOT NULL
        );

        -- Skip when no row has a key: the dedup probes' HOLDLOCK range locks (held to commit) would
        -- otherwise serialize every concurrent keyless enqueue on the namespace.
        IF
            EXISTS (
                SELECT 1 FROM @p_batch
                WHERE deduplication_key IS NOT NULL
            )
            BEGIN
                INSERT INTO @existing (ordinal, id, job_ref)
                SELECT
                    b.ordinal,
                    j.id,
                    j.job_ref
                FROM @p_batch b
                INNER JOIN acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                    ON
                        j.parent_id = b.parent_id
                        AND j.deduplication_key = b.deduplication_key
                WHERE
                    b.deduplication_key IS NOT NULL
                    AND b.parent_id IS NOT NULL;

                INSERT INTO @existing (ordinal, id, job_ref)
                SELECT
                    b.ordinal,
                    j.id,
                    j.job_ref
                FROM @p_batch b
                INNER JOIN @resolved r ON r.ordinal = b.ordinal
                INNER JOIN acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                    ON
                        j.namespace_id = r.ns_id
                        AND j.deduplication_key = b.deduplication_key
                        AND j.parent_id IS NULL
                WHERE
                    b.deduplication_key IS NOT NULL
                    AND b.parent_id IS NULL;
            END;

        DECLARE @parents TABLE (
            ordinal INT PRIMARY KEY,
            lineage_root_id BIGINT NOT NULL,
            correlation_key VARCHAR(64) NULL,
            tenant_id INT NULL
        );

        INSERT INTO @parents (ordinal, lineage_root_id, correlation_key, tenant_id)
        SELECT
            b.ordinal,
            COALESCE(pj.lineage_root_id, pj.id),
            pj.correlation_key,
            pj.tenant_id
        FROM @p_batch b
        INNER JOIN acta.jobs pj WITH (UPDLOCK, ROWLOCK) ON pj.id = b.parent_id
        INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
        WHERE
            b.parent_id IS NOT NULL
            AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
        ORDER BY pj.id DESC;

        IF (
            SELECT COUNT(*) FROM @parents) < (
            SELECT COUNT(*) FROM @p_batch
            WHERE parent_id IS NOT NULL
        )
            BEGIN
                THROW 50002, 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.', 1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                LEFT JOIN @parents p ON p.ordinal = b.ordinal
                WHERE
                    r.def_tenant_req = 10 /* JobTenantRequirementCode.Required */
                    AND r.tenant_id IS NULL
                    AND p.tenant_id IS NULL
            )
            BEGIN
                THROW 50007,
                'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: one or more rows target a definition that requires a tenant and carry none.',
                1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                WHERE
                    r.def_tenant_req = 20 /* JobTenantRequirementCode.Forbidden */
                    AND b.tenant_key IS NOT NULL
            )
            BEGIN
                THROW 50008,
                'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: one or more rows target a definition that forbids a tenant and name one.',
                1;
            END;

        IF
            EXISTS (
                SELECT 1
                FROM @resolved r
                INNER JOIN @p_batch b ON b.ordinal = r.ordinal
                INNER JOIN @parents p ON p.ordinal = b.ordinal
                WHERE
                    r.tenant_id IS NOT NULL
                    AND p.tenant_id IS NOT NULL
                    AND r.tenant_id <> p.tenant_id
                    AND b.tenant_override = 0
            )
            BEGIN
                DECLARE
                    @tenant_msg NVARCHAR(2048) = 'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: one or more child rows name a'
                    + ' TenantKey that differs from the parent tenant without an explicit override.';
                THROW 50009, @tenant_msg, 1;
            END;

        DECLARE @map TABLE (
            job_ref UNIQUEIDENTIFIER PRIMARY KEY,
            id BIGINT NOT NULL
        );

        INSERT INTO acta.jobs (
            job_ref, lineage_root_id, parent_id,
            deduplication_key, correlation_key,
            namespace_id, definition_id, tenant_id,
            input_format_id, input,
            exclusive_key, audit_level_code,
            created_at_utc
        )
        OUTPUT INSERTED.job_ref, INSERTED.id INTO @map (job_ref, id)
        SELECT
            b.job_ref,
            p.lineage_root_id,
            b.parent_id,
            b.deduplication_key,
            COALESCE(b.correlation_key, p.correlation_key),
            r.ns_id,
            r.def_id,
            CASE
                WHEN r.def_tenant_req = 20 /* JobTenantRequirementCode.Forbidden */ THEN NULL
                ELSE COALESCE(r.tenant_id, p.tenant_id)
            END,
            b.input_format_id,
            b.input,
            b.exclusive_key,
            r.def_audit_level,
            @now
        FROM @p_batch b
        INNER JOIN @resolved r ON r.ordinal = b.ordinal
        LEFT JOIN @parents p ON p.ordinal = b.ordinal
        LEFT JOIN @existing e ON e.ordinal = b.ordinal
        WHERE e.ordinal IS NULL;

        INSERT INTO acta.runtimes (
            job_id, namespace_id, status_code, priority_code, next_run_at_utc,
            execution_number, failure_count, retention_until_utc,
            modified_at_utc, version
        )
        SELECT
            m.id,
            r.ns_id,
            10 /* JobStatusCode.Ready */,
            COALESCE(b.priority_override, r.def_priority),
            COALESCE(b.next_run_at_utc, DATEADD(SECOND, COALESCE(b.delay_seconds, 0), @now)),
            0,
            0,
            NULL,
            @now,
            0
        FROM @map m
        INNER JOIN @p_batch b ON b.job_ref = m.job_ref
        INNER JOIN @resolved r ON r.ordinal = b.ordinal;

        INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT
            50 /* TagScopeCode.Job */,
            m.id,
            r.ns_id,
            t.name,
            t.value,
            t.value_search
        FROM @p_tag_batch t
        INNER JOIN @p_batch b ON b.ordinal = t.ordinal
        INNER JOIN @map m ON m.job_ref = b.job_ref
        INNER JOIN @resolved r ON r.ordinal = t.ordinal;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        b.ordinal,
        COALESCE(m.id, e.id) AS job_id,
        COALESCE(m.job_ref, e.job_ref) AS job_ref,
        CASE
            WHEN m.id IS NOT NULL
                THEN 1 /* JobEnqueueAction.Inserted */
            ELSE 2 /* JobEnqueueAction.Deduplicated */
        END AS action
    FROM @p_batch b
    LEFT JOIN @map m ON m.job_ref = b.job_ref
    LEFT JOIN @existing e ON e.ordinal = b.ordinal
    ORDER BY b.ordinal;
END;
GO
-- Only @p_namespace_name and @p_job_name are required; other scalars default (@p_job_ref is
-- server-generated when omitted; @p_input_format_id defaults json/none by input presence). The tag TVP
-- has no default (SQL Server TVPs cannot); pass an empty table variable for a tag-free enqueue.
CREATE OR ALTER PROCEDURE acta.enqueue_one
    @p_job_ref UNIQUEIDENTIFIER = NULL,
    @p_namespace_name VARCHAR(128) = NULL,
    @p_job_name VARCHAR(128) = NULL,
    @p_deduplication_key VARCHAR(128) = NULL,
    @p_correlation_key VARCHAR(64) = NULL,
    @p_priority_override TINYINT = NULL,
    @p_input_format_id TINYINT = NULL,
    @p_input VARBINARY(MAX) = NULL,
    @p_exclusive_key VARCHAR(128) = NULL,
    @p_next_run_at_utc DATETIME2(3) = NULL,
    @p_delay_seconds INT = NULL,
    @p_parent_id BIGINT = NULL,
    @p_tenant_key VARCHAR(128) = NULL,
    @p_tenant_override BIT = 0,
    @p_tag_batch acta.job_enqueue_tag_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @ns_id SMALLINT, @ns_status TINYINT, @def_id INT, @def_priority SMALLINT;
    DECLARE @def_audit TINYINT, @def_status TINYINT, @def_tenant_req TINYINT;
    DECLARE @tenant_id INT, @tenant_status TINYINT, @lineage BIGINT, @parent_corr VARCHAR(64), @parent_tenant INT;
    DECLARE @existing_id BIGINT, @existing_ref UNIQUEIDENTIFIER, @job_id BIGINT;

    -- Own a local transaction only when invoked outside one. Inside a caller's transaction (direct
    -- transactional enqueue) the entry count is > 0: run the work but neither commit nor roll back it;
    -- on error rethrow and let the caller roll back the whole transaction.
    DECLARE @entry_trancount INT = @@TRANCOUNT;

    -- Server-generate the job ref when the caller omits it (a proc default cannot be NEWID()).
    SET @p_job_ref = COALESCE(@p_job_ref, NEWID());

    BEGIN TRY
        IF @entry_trancount = 0
            BEGIN TRANSACTION;

        SELECT
            @ns_id = ns.id,
            @ns_status = ns.status_code,
            @def_id = jd.id,
            @def_priority = jd.priority_code_effective,
            @def_audit = jd.audit_level_code_effective,
            @def_status = jd.status_code,
            @def_tenant_req = jd.tenant_requirement_code
        FROM acta.namespaces ns
        INNER JOIN acta.definitions jd
            ON
                jd.namespace_id = ns.id
                AND jd.name = @p_job_name
        WHERE ns.name = @p_namespace_name;

        IF @def_id IS NULL
            BEGIN
                DECLARE
                    @route_msg NVARCHAR(2048) = 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown'
                    + ' namespace or job. Has the owning worker run InitializeAsync yet?';
                THROW 50001, @route_msg, 1;
            END;

        IF @ns_status <> 10 /* NamespaceStatusCode.Active */
            BEGIN
                THROW 50005, 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.', 1;
            END;

        IF @def_status <> 10 /* JobDefinitionStatusCode.Active */
            BEGIN
                THROW 50003, 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.', 1;
            END;

        IF @p_tenant_key IS NOT NULL
            BEGIN
                SELECT
                    @tenant_id = t.id,
                    @tenant_status = t.status_code
                FROM acta.tenants t
                WHERE t.tenant_key = @p_tenant_key;

                IF @tenant_id IS NULL
                    BEGIN
                        THROW 50004, 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.', 1;
                    END;

                IF @tenant_status <> 10 /* TenantStatusCode.Active */
                    BEGIN
                        THROW 50006, 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.', 1;
                    END;
            END;

        IF @def_tenant_req = 20 /* JobTenantRequirementCode.Forbidden */ AND @p_tenant_key IS NOT NULL
            BEGIN
                THROW 50008, 'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: the job definition forbids a tenant and the row names one.', 1;
            END;

        IF @p_deduplication_key IS NOT NULL
            BEGIN
                IF @p_parent_id IS NOT NULL
                    BEGIN
                        SELECT
                            @existing_id = j.id,
                            @existing_ref = j.job_ref
                        FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                        WHERE
                            j.parent_id = @p_parent_id
                            AND j.deduplication_key = @p_deduplication_key;
                    END
                ELSE
                    BEGIN
                        SELECT
                            @existing_id = j.id,
                            @existing_ref = j.job_ref
                        FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK)
                        WHERE
                            j.namespace_id = @ns_id
                            AND j.deduplication_key = @p_deduplication_key
                            AND j.parent_id IS NULL;
                    END;
            END;

        IF @p_parent_id IS NOT NULL
            BEGIN
                SELECT
                    @lineage = COALESCE(pj.lineage_root_id, pj.id),
                    @parent_corr = pj.correlation_key,
                    @parent_tenant = pj.tenant_id
                FROM acta.jobs pj WITH (UPDLOCK, ROWLOCK)
                INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
                WHERE
                    pj.id = @p_parent_id
                    AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */);

                IF @lineage IS NULL
                    BEGIN
                        THROW 50002, 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.', 1;
                    END;
            END;

        IF @def_tenant_req = 10 /* JobTenantRequirementCode.Required */ AND @tenant_id IS NULL AND @parent_tenant IS NULL
            BEGIN
                THROW 50007, 'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: the job definition requires a tenant and the row carries none.', 1;
            END;

        IF @tenant_id IS NOT NULL AND @parent_tenant IS NOT NULL AND @tenant_id <> @parent_tenant AND @p_tenant_override = 0
            BEGIN
                THROW 50009,
                'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: a child TenantKey differs from the parent tenant without an explicit override.',
                1;
            END;

        IF @existing_id IS NULL
            BEGIN
                INSERT INTO acta.jobs (
                    job_ref, lineage_root_id, parent_id,
                    deduplication_key, correlation_key,
                    namespace_id, definition_id, tenant_id,
                    input_format_id, input,
                    exclusive_key, audit_level_code,
                    created_at_utc
                )
                VALUES (
                    @p_job_ref, @lineage, @p_parent_id,
                    @p_deduplication_key, COALESCE(@p_correlation_key, @parent_corr),
                    @ns_id, @def_id,
                    CASE
                        WHEN @def_tenant_req = 20 /* JobTenantRequirementCode.Forbidden */ THEN NULL
                        ELSE COALESCE(@tenant_id, @parent_tenant)
                    END,
                    COALESCE(
                        @p_input_format_id,
                        CASE WHEN @p_input IS NULL THEN 0 /* JobPayloadFormat.None */ ELSE 1 /* JobPayloadFormat.Json */ END
                    ),
                    @p_input,
                    @p_exclusive_key, @def_audit,
                    @now
                );

                SET @job_id = SCOPE_IDENTITY();

                INSERT INTO acta.runtimes (
                    job_id, namespace_id, status_code, priority_code, next_run_at_utc,
                    execution_number, failure_count, retention_until_utc,
                    modified_at_utc, version
                )
                VALUES (
                    @job_id, @ns_id, 10 /* JobStatusCode.Ready */,
                    COALESCE(@p_priority_override, @def_priority),
                    COALESCE(@p_next_run_at_utc, DATEADD(SECOND, COALESCE(@p_delay_seconds, 0), @now)),
                    0, 0, NULL,
                    @now, 0
                );

                INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
                SELECT
                    50 /* TagScopeCode.Job */,
                    @job_id,
                    @ns_id,
                    t.name,
                    t.value,
                    t.value_search
                FROM @p_tag_batch t;
            END;

        IF @entry_trancount = 0
            COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @entry_trancount = 0 AND XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        0 AS ordinal,
        COALESCE(@job_id, @existing_id) AS job_id,
        CASE WHEN @job_id IS NOT NULL THEN @p_job_ref ELSE @existing_ref END AS job_ref,
        CASE
            WHEN @job_id IS NOT NULL
                THEN 1 /* JobEnqueueAction.Inserted */
            ELSE 2 /* JobEnqueueAction.Deduplicated */
        END AS action;
END;
GO
CREATE OR ALTER PROCEDURE acta.pause_job
    @p_id BIGINT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT,
        @lineage_root_id BIGINT, @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
        @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                RETURN;
            END;

        IF
            @from_status NOT IN (
                30 /* JobStatusCode.Paused */,
                20 /* JobStatusCode.Suspended */,
                10 /* JobStatusCode.Ready */
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        UPDATE acta.runtimes
        SET
            status_code = 30 /* JobStatusCode.Paused */,
            modified_at_utc = @now,
            version = version + 1
        WHERE job_id = @p_id;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    71 /* EventCode.JobPaused */, @now, @namespace_id,
                    @p_actor_code, @p_actor_key,
                    @p_id, @job_ref, @execution_number,
                    COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                    NULL,
                    @from_status, 30 /* JobStatusCode.Paused */,
                    NULL, NULL,
                    @p_reason_code, @p_reason_message
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            CAST(30 /* JobStatusCode.Paused */ AS TINYINT) AS status_code;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.purge_job
    @p_id BIGINT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT,
        @definition_id INT, @tenant_id INT,
        @job_ref UNIQUEIDENTIFIER, @job_name VARCHAR(128);

    BEGIN TRY
        BEGIN TRANSACTION;

        /* Lock the jobs row too: child enqueue locks jobs (not runtimes), and under RCSI the
           child guard below only serializes if we hold the same resource. */
        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @job_ref = j.job_ref,
            @job_name = d.name
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j WITH (UPDLOCK, ROWLOCK) ON j.id = r.job_id
        INNER JOIN acta.definitions d ON d.id = j.definition_id
        WHERE r.job_id = @p_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                RETURN;
            END;

        IF
            @from_status NOT IN (
                100 /* JobStatusCode.Succeeded */,
                200 /* JobStatusCode.Failed */,
                220 /* JobStatusCode.Cancelled */
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        -- parent_id carries no DB FK/cascade; purging a job that has child jobs would orphan the child's
        -- lineage, so reject.
        IF
            EXISTS (
                SELECT 1 FROM acta.jobs c
                WHERE c.parent_id = @p_id
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        DECLARE @schedule_ids TABLE (id BIGINT PRIMARY KEY);
        DECLARE @alert_ids TABLE (id BIGINT PRIMARY KEY);
        DECLARE @event_ids TABLE (id BIGINT PRIMARY KEY);

        INSERT @schedule_ids SELECT id FROM acta.schedules WITH (UPDLOCK, ROWLOCK)
        WHERE job_id = @p_id;
        INSERT @alert_ids SELECT id FROM acta.alerts WITH (UPDLOCK, ROWLOCK)
        WHERE job_id = @p_id;
        INSERT @event_ids SELECT id FROM acta.events WITH (UPDLOCK, ROWLOCK)
        WHERE job_id = @p_id;

        DELETE FROM acta.tags
        WHERE
            (scope_code = 50 /* TagScopeCode.Job */ AND scope_id = @p_id)
            OR (scope_code = 60 /* TagScopeCode.Schedule */ AND scope_id IN (SELECT id FROM @schedule_ids))
            OR (scope_code = 80 /* TagScopeCode.Alert */ AND scope_id IN (SELECT id FROM @alert_ids))
            OR (scope_code = 90 /* TagScopeCode.Event */ AND scope_id IN (SELECT id FROM @event_ids));

        DELETE FROM acta.events
        WHERE job_id = @p_id;
        DELETE FROM acta.alerts
        WHERE job_id = @p_id;
        DELETE FROM acta.jobs
        WHERE id = @p_id;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor_key,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        VALUES (
            75 /* EventCode.JobPurged */, @now, @namespace_id,
            @p_actor_code, @p_actor_key,
            NULL, NULL, NULL,
            NULL, @definition_id, @tenant_id,
            NULL,
            @from_status, NULL,
            NULL, NULL,
            @p_reason_code, CONCAT('purged ', LOWER(CONVERT(VARCHAR(36), @job_ref)), ' (', @job_name, ')')
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            CAST(NULL AS TINYINT) AS status_code;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.reprioritize_job
    @p_id BIGINT,
    @p_priority_code TINYINT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT,
        @lineage_root_id BIGINT, @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
        @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                RETURN;
            END;

        IF
            @from_status IN (
                100 /* JobStatusCode.Succeeded */,
                200 /* JobStatusCode.Failed */,
                220 /* JobStatusCode.Cancelled */
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        UPDATE acta.runtimes
        SET
            priority_code = @p_priority_code,
            modified_at_utc = @now,
            version = version + 1
        WHERE job_id = @p_id;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    74 /* EventCode.JobReprioritized */, @now, @namespace_id,
                    @p_actor_code, @p_actor_key,
                    @p_id, @job_ref, @execution_number,
                    COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                    NULL,
                    NULL, NULL,
                    NULL, NULL,
                    @p_reason_code, @p_reason_message
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @from_status AS status_code;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.reschedule_job
    @p_id BIGINT,
    @p_next_run_at_utc DATETIME2(7),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT,
        @lineage_root_id BIGINT, @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
        @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                RETURN;
            END;

        IF
            @from_status NOT IN (
                30 /* JobStatusCode.Paused */,
                20 /* JobStatusCode.Suspended */,
                10 /* JobStatusCode.Ready */
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        UPDATE acta.runtimes
        SET
            next_run_at_utc = @p_next_run_at_utc,
            status_code = 10 /* JobStatusCode.Ready */,
            modified_at_utc = @now,
            version = version + 1
        WHERE job_id = @p_id;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    61 /* EventCode.JobRescheduled */, @now, @namespace_id,
                    @p_actor_code, @p_actor_key,
                    @p_id, @job_ref, @execution_number,
                    COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                    NULL,
                    @from_status, 10 /* JobStatusCode.Ready */,
                    NULL, NULL,
                    @p_reason_code, @p_reason_message
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            CAST(10 /* JobStatusCode.Ready */ AS TINYINT) AS status_code;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.reset_job_state
    @p_id BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @status TINYINT, @namespace_id SMALLINT,
        @lineage_root_id BIGINT, @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
        @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_id;

        IF @status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                RETURN;
            END;

        DELETE FROM acta.checkpoints
        WHERE job_id = @p_id;
        DELETE FROM acta.steps
        WHERE job_id = @p_id;
        DELETE FROM acta.results
        WHERE job_id = @p_id;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    81 /* EventCode.JobStateReset */, @now, @namespace_id,
                    50 /* ActorCode.Job */, CONVERT(VARCHAR(128), @p_id),
                    @p_id, @job_ref, @execution_number,
                    COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                    NULL,
                    @status, @status,
                    NULL, NULL,
                    NULL, NULL
                );
            END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
