CREATE OR ALTER PROCEDURE acta.update_job_input
    @p_id BIGINT,
    @p_input_format_id TINYINT,
    @p_input VARBINARY(MAX),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT,
        @lineage_root_id BIGINT, @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
        @job_ref UNIQUEIDENTIFIER, @old_format_id TINYINT, @old_input VARBINARY(MAX);
    DECLARE @detail VARBINARY(MAX);
    DECLARE @detail_format_id TINYINT = 0 /* JobPayloadFormat.None */;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref,
            @old_format_id = j.input_format_id,
            @old_input = j.input
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                RETURN;
            END;

        IF
            @from_status IN (
                40 /* JobStatusCode.Dispatched */,
                50 /* JobStatusCode.Executing */
            )
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        UPDATE acta.jobs
        SET
            input = @p_input,
            input_format_id = @p_input_format_id
        WHERE id = @p_id;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            BEGIN
            -- The event carries only bounded JSON metadata about the previous payload (format name
            -- and byte count), never the payload itself. Pure ASCII, so VARCHAR -> VARBINARY is UTF-8.
                IF @old_format_id <> 0 /* JobPayloadFormat.None */
                    BEGIN
                        SET @detail_format_id = 1 /* JobPayloadFormat.Json */;
                        SET @detail = CONVERT(
                            VARBINARY(MAX),
                            '{"format":"'
                            + CASE @old_format_id
                                WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
                                WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
                                WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
                                ELSE 'custom-' + CONVERT(VARCHAR(3), @old_format_id)
                            END
                            + '","bytes":' + CONVERT(VARCHAR(20), DATALENGTH(@old_input)) + '}'
                        );
                    END;

                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    detail_format_id, detail,
                    reason_code, reason_message
                )
                VALUES (
                    76 /* EventCode.JobInputAmended */, @now, @namespace_id,
                    @p_actor_code, @p_actor_key,
                    @p_id, @job_ref, @execution_number,
                    COALESCE(@lineage_root_id, @p_id), @definition_id, @tenant_id,
                    NULL,
                    NULL, NULL,
                    NULL, NULL,
                    @detail_format_id, @detail,
                    @p_reason_code, @p_reason_message
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @from_status AS status_code;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.resume_namespace
    @p_namespace_name VARCHAR(128),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @id SMALLINT, @status TINYINT, @version INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT
            @id = n.id,
            @status = n.status_code,
            @version = n.version
        FROM acta.namespaces n WITH (UPDLOCK, ROWLOCK)
        WHERE n.name = @p_namespace_name;

        IF @id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @status = 10 /* NamespaceStatusCode.Active */
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* AdminControlAction.AlreadyInState */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        UPDATE acta.namespaces
        SET status_code = 10 /* NamespaceStatusCode.Active */, modified_at_utc = @now, version = version + 1
        WHERE id = @id;
        SET @version = @version + 1;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            21 /* EventCode.NamespaceResumed */, @now, @id, @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, NULL, NULL, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.suspend_namespace
    @p_namespace_name VARCHAR(128),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @id SMALLINT, @status TINYINT, @version INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT
            @id = n.id,
            @status = n.status_code,
            @version = n.version
        FROM acta.namespaces n WITH (UPDLOCK, ROWLOCK)
        WHERE n.name = @p_namespace_name;

        IF @id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @status = 20 /* NamespaceStatusCode.Suspended */
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* AdminControlAction.AlreadyInState */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        UPDATE acta.namespaces
        SET status_code = 20 /* NamespaceStatusCode.Suspended */, modified_at_utc = @now, version = version + 1
        WHERE id = @id;
        SET @version = @version + 1;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            20 /* EventCode.NamespaceSuspended */, @now, @id, @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, NULL, NULL, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.update_namespace
    @p_namespace_name VARCHAR(128),
    @p_owner_team NVARCHAR(512),
    @p_description NVARCHAR(512),
    @p_expected_version INT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @id SMALLINT, @version INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT
            @id = n.id,
            @version = n.version
        FROM acta.namespaces n WITH (UPDLOCK, ROWLOCK)
        WHERE n.name = @p_namespace_name;

        IF @id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @version <> @p_expected_version
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(4 /* AdminControlAction.VersionConflict */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        UPDATE acta.namespaces
        SET owner_team = @p_owner_team, description = @p_description, modified_at_utc = @now, version = version + 1
        WHERE id = @id;
        SET @version = @version + 1;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            22 /* EventCode.NamespaceUpdated */, @now, @id, @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, NULL, NULL, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
-- Appends one application-authored job.note-recorded event; see IExecutionStore.RecordJobNoteAsync.
-- Denormalized columns are read from the job, so a note cannot disagree with the row it is about.
CREATE OR ALTER PROCEDURE acta.record_job_note
    @p_job_id BIGINT,
    @p_reason_message NVARCHAR(512),
    @p_detail_format_id TINYINT,
    @p_detail VARBINARY(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        detail_format_id,
        detail,
        reason_message)
    SELECT
        90 /* EventCode.JobNoteRecorded */,
        SYSUTCDATETIME(),
        j.namespace_id,
        50 /* ActorCode.Job */,
        j.id,
        j.job_ref,
        r.execution_number,
        COALESCE(j.lineage_root_id, j.id),
        j.definition_id,
        j.tenant_id,
        @p_detail_format_id,
        @p_detail,
        @p_reason_message
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = @p_job_id;

    IF @@ROWCOUNT = 0
    BEGIN
        THROW 50000, 'ACTA:NOTE_UNKNOWN_JOB:record_job_note: unknown job id', 1;
    END
END
GO
CREATE OR ALTER PROCEDURE acta.reclaim_stuck_jobs
    @p_namespace_id SMALLINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    DECLARE
        @reclaimed TABLE
        (
            id BIGINT NOT NULL PRIMARY KEY,
            job_ref UNIQUEIDENTIFIER NOT NULL,
            namespace_id SMALLINT NOT NULL,
            execution_number INT NOT NULL,
            lineage_root_id BIGINT NULL,
            definition_id INT NOT NULL,
            tenant_id INT NULL,
            from_status_code TINYINT NOT NULL,
            to_status_code TINYINT NOT NULL,
            audit_level_code TINYINT NOT NULL,
            parent_id BIGINT NULL
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        WITH stuck AS (
            SELECT
                r.job_id AS id,
                r.status_code AS from_status,
                (r.failure_count + 1) AS new_failure_count,
                jd.max_attempts_effective AS max_attempts,
                jd.retention_seconds_effective AS retention_seconds
            FROM acta.runtimes r WITH (READPAST, UPDLOCK, ROWLOCK)
            INNER JOIN acta.jobs j ON j.id = r.job_id
            INNER JOIN acta.definitions jd ON jd.id = j.definition_id
            WHERE
                r.status_code IN (40 /* JobStatusCode.Dispatched */, 50 /* JobStatusCode.Executing */)
                AND r.lease_expires_at_utc < @now
                AND r.namespace_id = @p_namespace_id
        )

        UPDATE r
        SET
            status_code = CASE
                WHEN s.new_failure_count >= s.max_attempts
                    THEN 200 /* JobStatusCode.Failed */
                ELSE 10  /* JobStatusCode.Ready */
            END,
            failure_count = s.new_failure_count,
            next_run_at_utc = CASE
                WHEN s.new_failure_count >= s.max_attempts
                    THEN r.next_run_at_utc
                ELSE @now
            END,
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = CASE
                WHEN s.new_failure_count >= s.max_attempts
                    THEN DATEADD(SECOND, s.retention_seconds, @now)
                ELSE r.retention_until_utc
            END,
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id, j.job_ref, j.namespace_id, INSERTED.execution_number,
            j.lineage_root_id, j.definition_id, j.tenant_id,
            DELETED.status_code, INSERTED.status_code, j.audit_level_code,
            j.parent_id
        INTO
            @reclaimed (
                id, job_ref, namespace_id, execution_number, lineage_root_id,
                definition_id, tenant_id, from_status_code, to_status_code, audit_level_code, parent_id
            )
        FROM acta.runtimes r
        INNER JOIN stuck s ON s.id = r.job_id
        INNER JOIN acta.jobs j ON j.id = r.job_id;

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id,
            actor_code, actor_key,
            job_id, job_ref, execution_number,
            lineage_root_id, definition_id, tenant_id,
            worker_id,
            from_status_code, to_status_code,
            execution_status_code, duration_ms,
            reason_code, reason_message
        )
        SELECT
            41 /* EventCode.JobExecutionFinished */,
            @now,
            namespace_id,
            10 /* ActorCode.Sys */,
            NULL,
            id,
            job_ref,
            execution_number,
            COALESCE(lineage_root_id, id),
            definition_id,
            tenant_id,
            NULL,
            from_status_code,
            to_status_code,
            230 /* ExecutionStatusCode.Orphaned */,
            NULL,
            21 /* JobEventReasonCode.JobLeaseExpired */,
            N'Worker lease expired; reclaimed by the sys.recovery system job.'
        FROM @reclaimed
        WHERE audit_level_code IN (10 /* JobAuditLevelCode.Failures */, 20 /* JobAuditLevelCode.Audit */);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        id AS job_id,
        to_status_code AS to_status,
        parent_id
    FROM @reclaimed;
END;
GO
CREATE OR ALTER PROCEDURE acta.pause_schedule
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_paused_until_utc DATETIME2(7),
    @p_job_next_run_at_utc DATETIME2(7),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @schedule_id BIGINT, @status TINYINT, @paused DATETIME2(7), @next DATETIME2(7), @version INT;
    DECLARE @ns SMALLINT, @def INT, @lineage BIGINT, @en INT, @audit TINYINT, @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
           runtimes then schedules, so every writer of both must take runtimes first. */
        SELECT @en = r.execution_number
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        WHERE r.job_id = @p_job_id;

        SELECT @schedule_id = js.id
        FROM acta.schedules js WITH (UPDLOCK, ROWLOCK)
        WHERE
            js.job_id = @p_job_id
            AND js.name = @p_name
            AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */;

        IF @schedule_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code,
                    CAST(NULL AS DATETIME2(7)) AS paused_until_utc,
                    CAST(NULL AS DATETIME2(7)) AS next_run_at_utc,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        SELECT
            @ns = j.namespace_id,
            @def = j.definition_id,
            @lineage = j.lineage_root_id,
            @audit = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.jobs j
        WHERE j.id = @p_job_id;

        UPDATE acta.schedules
        SET
            status_code = 30 /* ScheduleStatusCode.Paused */,
            paused_until_utc = @p_paused_until_utc,
            reason_message = @p_reason_message,
            modified_at_utc = @now,
            version = version + 1
        WHERE id = @schedule_id;

        SELECT
            @status = status_code,
            @paused = paused_until_utc,
            @next = next_run_at_utc,
            @version = version
        FROM acta.schedules
        WHERE id = @schedule_id;

        UPDATE acta.runtimes
        SET
            next_run_at_utc = @p_job_next_run_at_utc,
            status_code = CASE
                WHEN @p_job_next_run_at_utc IS NULL
                    THEN 30 /* JobStatusCode.Paused */
                ELSE 10 /* JobStatusCode.Ready */
            END,
            modified_at_utc = @now,
            version = version + 1
        WHERE
            job_id = @p_job_id
            AND status_code IN (30 /* JobStatusCode.Paused */, 10 /* JobStatusCode.Ready */);

        IF @audit = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    100 /* EventCode.SchedulePaused */, @now, @ns,
                    @p_actor_code, @p_actor_key,
                    @p_job_id, @job_ref, @en,
                    COALESCE(@lineage, @p_job_id), @def,
                    NULL,
                    NULL, NULL,
                    NULL, NULL,
                    NULL, @p_name
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @status AS status_code,
            @paused AS paused_until_utc,
            @next AS next_run_at_utc,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.register_scheduled_jobs
    @p_namespace_id SMALLINT,
    @p_definitions acta.job_schedule_slot_batch READONLY,
    @p_schedules acta.job_schedule_upsert_batch READONLY
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @lock_result INT;
    DECLARE @lock_resource NVARCHAR(255) = N'acta.register_scheduled_jobs';

    BEGIN TRY
        BEGIN TRANSACTION;

        EXEC @lock_result = sys.sp_getapplock @lock_resource, 'Exclusive', 'Transaction';

        IF @lock_result < 0
            BEGIN
                THROW 50004, 'register_scheduled_jobs could not acquire the recurring slot lock.', 1;
            END

        UPDATE j
        SET
            input_format_id = d.input_format_id,
            input = d.input,
            audit_level_code = d.audit_level_code
        FROM acta.jobs AS j
        INNER JOIN @p_definitions AS d ON d.deduplication_key = j.deduplication_key
        WHERE
            j.namespace_id = @p_namespace_id
            AND j.parent_id IS NULL;

        -- Re-registration re-asserts the definition's declared priority onto the slot, overwriting any operator reprioritize.
        UPDATE r
        SET
            status_code = d.slot_status_code,
            priority_code = jd.priority_code_effective,
            next_run_at_utc = d.slot_next_run_at_utc,
            modified_at_utc = @now,
            version = r.version + 1
        FROM acta.runtimes AS r
        INNER JOIN acta.jobs AS j ON j.id = r.job_id
        INNER JOIN @p_definitions AS d ON d.deduplication_key = j.deduplication_key
        INNER JOIN acta.definitions AS jd ON jd.id = d.definition_id
        WHERE
            j.namespace_id = @p_namespace_id
            AND j.parent_id IS NULL;

        INSERT INTO acta.jobs (
            job_ref, lineage_root_id, parent_id, deduplication_key, correlation_key,
            namespace_id, definition_id,
            input_format_id, input,
            exclusive_key, audit_level_code,
            created_at_utc
        )
        SELECT
            d.job_ref,
            NULL,
            NULL,
            d.deduplication_key,
            NULL,
            @p_namespace_id,
            d.definition_id,
            d.input_format_id,
            d.input,
            NULL,
            d.audit_level_code,
            @now
        FROM @p_definitions AS d
        WHERE NOT EXISTS (
            SELECT 1
            FROM acta.jobs AS j
            WHERE
                j.namespace_id = @p_namespace_id
                AND j.deduplication_key = d.deduplication_key
                AND j.parent_id IS NULL
        );

        INSERT INTO acta.runtimes (
            job_id, namespace_id, status_code, priority_code, next_run_at_utc,
            execution_number, failure_count, retention_until_utc,
            modified_at_utc, version
        )
        SELECT
            j.id,
            @p_namespace_id,
            d.slot_status_code,
            jd.priority_code_effective,
            d.slot_next_run_at_utc,
            0,
            0,
            NULL,
            @now,
            0
        FROM @p_definitions AS d
        INNER JOIN acta.jobs AS j
            ON
                j.namespace_id = @p_namespace_id
                AND j.deduplication_key = d.deduplication_key
                AND j.parent_id IS NULL
        INNER JOIN acta.definitions AS jd ON jd.id = d.definition_id
        WHERE NOT EXISTS (
            SELECT 1 FROM acta.runtimes AS r
            WHERE r.job_id = j.id
        );

        DECLARE @slots TABLE (definition_id INT NOT NULL PRIMARY KEY, slot_id BIGINT NOT NULL);

        INSERT INTO @slots (definition_id, slot_id)
        SELECT
            d.definition_id,
            j.id
        FROM @p_definitions AS d
        INNER JOIN acta.jobs AS j
            ON
                j.namespace_id = @p_namespace_id
                AND j.deduplication_key = d.deduplication_key
                AND j.parent_id IS NULL;

        UPDATE tgt
        SET
            expression = src.expression,
            time_zone_id = src.time_zone_id,
            expression_kind_code = src.expression_kind_code,
            misfire_strategy_code = src.misfire_strategy_code,
            next_run_at_utc = src.next_run_at_utc,
            definition_id = src.definition_id,
            status_code = CASE
                WHEN tgt.status_code = 230 /* ScheduleStatusCode.Orphaned */
                    THEN 10 /* ScheduleStatusCode.Active */
                ELSE tgt.status_code
            END,
            description = src.description,
            modified_at_utc = @now,
            version = tgt.version + 1
        FROM acta.schedules AS tgt
        INNER JOIN @slots AS sl ON sl.slot_id = tgt.job_id
        INNER JOIN @p_schedules AS src
            ON
                src.definition_id = sl.definition_id
                AND src.name = tgt.name;

        INSERT INTO acta.schedules (
            namespace_id, job_id, definition_id, name, origin_code,
            expression, time_zone_id, expression_kind_code, misfire_strategy_code,
            next_run_at_utc, expression_override, time_zone_id_override,
            status_code, paused_until_utc, description,
            created_at_utc, modified_at_utc, version
        )
        SELECT
            @p_namespace_id,
            sl.slot_id,
            src.definition_id,
            src.name,
            40 /* ScheduleOriginCode.Definition */,
            src.expression,
            src.time_zone_id,
            src.expression_kind_code,
            src.misfire_strategy_code,
            src.next_run_at_utc,
            NULL,
            NULL,
            10 /* ScheduleStatusCode.Active */,
            NULL,
            src.description,
            @now,
            @now,
            0
        FROM @p_schedules AS src
        INNER JOIN @slots AS sl ON sl.definition_id = src.definition_id
        WHERE NOT EXISTS (
            SELECT 1
            FROM acta.schedules AS tgt
            WHERE
                tgt.job_id = sl.slot_id
                AND tgt.name = src.name
        );

        DECLARE @candidates TABLE (id BIGINT NOT NULL PRIMARY KEY);

        INSERT INTO @candidates (id)
        SELECT js.id
        FROM acta.schedules AS js
        INNER JOIN @slots AS sl ON sl.slot_id = js.job_id
        WHERE
            js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
            AND js.origin_code = 40 /* ScheduleOriginCode.Definition */
            AND NOT EXISTS (
                SELECT 1
                FROM @p_schedules AS src
                WHERE
                    src.definition_id = sl.definition_id
                    AND src.name = js.name
            );

        UPDATE js
        SET
            status_code = 230 /* ScheduleStatusCode.Orphaned */,
            paused_until_utc = NULL,
            modified_at_utc = @now,
            version = js.version + 1
        FROM acta.schedules AS js
        INNER JOIN @candidates AS c ON c.id = js.id;

        COMMIT TRANSACTION;

        SELECT
            definition_id,
            slot_id
        FROM @slots;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.resume_schedule
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_next_run_at_utc DATETIME2(7),
    @p_job_next_run_at_utc DATETIME2(7),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @schedule_id BIGINT, @status TINYINT, @paused DATETIME2(7), @next DATETIME2(7), @version INT;
    DECLARE @ns SMALLINT, @def INT, @lineage BIGINT, @en INT, @audit TINYINT, @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
           runtimes then schedules, so every writer of both must take runtimes first. */
        SELECT @en = r.execution_number
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        WHERE r.job_id = @p_job_id;

        SELECT @schedule_id = js.id
        FROM acta.schedules js WITH (UPDLOCK, ROWLOCK)
        WHERE
            js.job_id = @p_job_id
            AND js.name = @p_name
            AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */;

        IF @schedule_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code,
                    CAST(NULL AS DATETIME2(7)) AS paused_until_utc,
                    CAST(NULL AS DATETIME2(7)) AS next_run_at_utc,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        SELECT
            @ns = j.namespace_id,
            @def = j.definition_id,
            @lineage = j.lineage_root_id,
            @audit = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.jobs j
        WHERE j.id = @p_job_id;

        UPDATE acta.schedules
        SET
            status_code = 10 /* ScheduleStatusCode.Active */,
            paused_until_utc = NULL,
            next_run_at_utc = @p_next_run_at_utc,
            reason_message = @p_reason_message,
            modified_at_utc = @now,
            version = version + 1
        WHERE id = @schedule_id;

        SELECT
            @status = status_code,
            @paused = paused_until_utc,
            @next = next_run_at_utc,
            @version = version
        FROM acta.schedules
        WHERE id = @schedule_id;

        UPDATE acta.runtimes
        SET
            next_run_at_utc = @p_job_next_run_at_utc,
            status_code = CASE
                WHEN @p_job_next_run_at_utc IS NULL
                    THEN 30 /* JobStatusCode.Paused */
                ELSE 10 /* JobStatusCode.Ready */
            END,
            modified_at_utc = @now,
            version = version + 1
        WHERE
            job_id = @p_job_id
            AND status_code IN (30 /* JobStatusCode.Paused */, 10 /* JobStatusCode.Ready */);

        IF @audit = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    101 /* EventCode.ScheduleResumed */, @now, @ns,
                    @p_actor_code, @p_actor_key,
                    @p_job_id, @job_ref, @en,
                    COALESCE(@lineage, @p_job_id), @def,
                    NULL,
                    NULL, NULL,
                    NULL, NULL,
                    NULL, @p_name
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @status AS status_code,
            @paused AS paused_until_utc,
            @next AS next_run_at_utc,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.set_schedule_overrides
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_expected_version INT,
    @p_expression VARCHAR(128),
    @p_time_zone_id VARCHAR(128),
    @p_reason_message NVARCHAR(512),
    @p_job_next_run_at_utc DATETIME2(7),
    @p_schedule_next_run_at_utc DATETIME2(7),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_change_summary NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @schedule_id BIGINT, @status TINYINT, @paused DATETIME2(7), @next DATETIME2(7), @version INT;
    DECLARE @ns SMALLINT, @def INT, @lineage BIGINT, @en INT, @audit TINYINT, @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
           runtimes then schedules, so every writer of both must take runtimes first. */
        SELECT @en = r.execution_number
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        WHERE r.job_id = @p_job_id;

        SELECT
            @schedule_id = js.id,
            @status = js.status_code,
            @paused = js.paused_until_utc,
            @next = js.next_run_at_utc,
            @version = js.version
        FROM acta.schedules js WITH (UPDLOCK, ROWLOCK)
        WHERE
            js.job_id = @p_job_id
            AND js.name = @p_name
            AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */;

        IF @schedule_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code,
                    CAST(NULL AS DATETIME2(7)) AS paused_until_utc,
                    CAST(NULL AS DATETIME2(7)) AS next_run_at_utc,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @version <> @p_expected_version
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @status AS status_code,
                    @paused AS paused_until_utc,
                    @next AS next_run_at_utc,
                    @version AS version;
                RETURN;
            END;

        SELECT
            @ns = j.namespace_id,
            @def = j.definition_id,
            @lineage = j.lineage_root_id,
            @audit = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.jobs j
        WHERE j.id = @p_job_id;

        UPDATE acta.schedules
        SET
            expression_override = @p_expression,
            time_zone_id_override = @p_time_zone_id,
            next_run_at_utc = @p_schedule_next_run_at_utc,
            reason_message = @p_reason_message,
            modified_at_utc = @now,
            version = version + 1
        WHERE id = @schedule_id;

        SELECT
            @status = status_code,
            @paused = paused_until_utc,
            @next = next_run_at_utc,
            @version = version
        FROM acta.schedules
        WHERE id = @schedule_id;

        UPDATE acta.runtimes
        SET
            next_run_at_utc = @p_job_next_run_at_utc,
            status_code = CASE
                WHEN @p_job_next_run_at_utc IS NULL
                    THEN 30 /* JobStatusCode.Paused */
                ELSE 10 /* JobStatusCode.Ready */
            END,
            modified_at_utc = @now,
            version = version + 1
        WHERE
            job_id = @p_job_id
            AND status_code IN (30 /* JobStatusCode.Paused */, 10 /* JobStatusCode.Ready */);

        IF @audit = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    103 /* EventCode.ScheduleOverridesUpdated */, @now, @ns,
                    @p_actor_code, @p_actor_key,
                    @p_job_id, @job_ref, @en,
                    COALESCE(@lineage, @p_job_id), @def,
                    NULL,
                    NULL, NULL,
                    NULL, NULL,
                    NULL, @p_change_summary
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @status AS status_code,
            @paused AS paused_until_utc,
            @next AS next_run_at_utc,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.trigger_schedule_now
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @schedule_id BIGINT, @status TINYINT, @paused DATETIME2(7), @next DATETIME2(7), @version INT;
    DECLARE @slot_status TINYINT;
    DECLARE @ns SMALLINT, @def INT, @lineage BIGINT, @en INT, @audit TINYINT, @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
           runtimes then schedules, so every writer of both must take runtimes first. The schedules
           row is guard-only here (never updated): a manual trigger moves only the slot's cursor. */
        SELECT
            @slot_status = r.status_code,
            @en = r.execution_number
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        WHERE r.job_id = @p_job_id;

        SELECT
            @schedule_id = js.id,
            @status = js.status_code,
            @paused = js.paused_until_utc,
            @next = js.next_run_at_utc,
            @version = js.version
        FROM acta.schedules js WITH (UPDLOCK, ROWLOCK)
        WHERE
            js.job_id = @p_job_id
            AND js.name = @p_name
            AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */;

        IF @schedule_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code,
                    CAST(NULL AS DATETIME2(7)) AS paused_until_utc,
                    CAST(NULL AS DATETIME2(7)) AS next_run_at_utc,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @status = 30 /* ScheduleStatusCode.Paused */
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @status AS status_code,
                    @paused AS paused_until_utc,
                    @next AS next_run_at_utc,
                    @version AS version;
                RETURN;
            END;

        IF @slot_status IN (40 /* JobStatusCode.Dispatched */, 50 /* JobStatusCode.Executing */)
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @status AS status_code,
                    @paused AS paused_until_utc,
                    @next AS next_run_at_utc,
                    @version AS version;
                RETURN;
            END;

        IF @slot_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @status AS status_code,
                    @paused AS paused_until_utc,
                    @next AS next_run_at_utc,
                    @version AS version;
                RETURN;
            END;

        SELECT
            @ns = j.namespace_id,
            @def = j.definition_id,
            @lineage = j.lineage_root_id,
            @audit = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.jobs j
        WHERE j.id = @p_job_id;

        UPDATE acta.runtimes
        SET
            next_run_at_utc = @now,
            status_code = 10 /* JobStatusCode.Ready */,
            modified_at_utc = @now,
            version = version + 1
        WHERE
            job_id = @p_job_id
            AND status_code IN (30 /* JobStatusCode.Paused */, 20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */);

        IF @audit = 20 /* JobAuditLevelCode.Audit */
            BEGIN
                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                VALUES (
                    104 /* EventCode.ScheduleTriggered */, @now, @ns,
                    @p_actor_code, @p_actor_key,
                    @p_job_id, @job_ref, @en,
                    COALESCE(@lineage, @p_job_id), @def,
                    NULL,
                    NULL, NULL,
                    NULL, NULL,
                    NULL, @p_reason_message
                );
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @status AS status_code,
            @paused AS paused_until_utc,
            @next AS next_run_at_utc,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
-- Scoped upsert, last write wins: targets resolve the scope (none = Global, namespace alone =
-- Namespace, namespace + job name = Definition); unregistered targets are NotFound. UPDLOCK+HOLDLOCK
-- serializes same-key writers, so the guarded INSERT cannot lose a race. Name validated upstream.
CREATE OR ALTER PROCEDURE acta.set_setting
    @p_name VARCHAR(128),
    @p_value_format_id TINYINT,
    @p_value VARBINARY(MAX),
    @p_description NVARCHAR(512),
    @p_namespace_name VARCHAR(128),
    @p_job_name VARCHAR(128),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512),
    @p_expected_version INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @scope_code SMALLINT = 10 /* SettingScopeCode.Global */;
    DECLARE @namespace_id SMALLINT, @definition_id INT, @scope_id INT, @version INT;

    IF @p_namespace_name IS NOT NULL
        BEGIN
            SELECT @namespace_id = n.id FROM acta.namespaces n
            WHERE n.name = @p_namespace_name;
            IF @namespace_id IS NULL
                BEGIN
                    SELECT
                        CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                        CAST(NULL AS INT) AS version;
                    RETURN;
                END;
            IF @p_job_name IS NULL
                BEGIN
                    SET @scope_code = 30 /* SettingScopeCode.Namespace */; SET @scope_id = @namespace_id;
                END
            ELSE
                BEGIN
                    SELECT @definition_id = d.id
                    FROM acta.definitions d
                    WHERE d.namespace_id = @namespace_id AND d.name = @p_job_name;
                    IF @definition_id IS NULL
                        BEGIN
                            SELECT
                                CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                                CAST(NULL AS INT) AS version;
                            RETURN;
                        END;
                    SET @scope_code = 40 /* SettingScopeCode.Definition */; SET @scope_id = @definition_id;
                END;
        END;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @version = s.version
        FROM acta.settings s WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
        WHERE
            s.scope_code = @scope_code
            AND ((@scope_id IS NULL AND s.scope_id IS NULL) OR s.scope_id = @scope_id)
            AND s.name = @p_name;

        -- CAS misses never create and never write the event: report the row as it stands.
        IF @p_expected_version IS NOT NULL AND @version IS NULL
            BEGIN
                ROLLBACK TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;
        IF @p_expected_version IS NOT NULL AND @version <> @p_expected_version
            BEGIN
                ROLLBACK TRANSACTION;
                SELECT
                    CAST(4 /* AdminControlAction.VersionConflict */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        IF @version IS NULL
            BEGIN
                INSERT INTO acta.settings
                (scope_code, scope_id, name, value_format_id, value, description, created_at_utc, modified_at_utc, version)
                VALUES (@scope_code, @scope_id, @p_name, @p_value_format_id, @p_value, @p_description, @now, @now, 0);
                SET @version = 0;
            END
        ELSE
            BEGIN
                UPDATE acta.settings
                SET
                    value_format_id = @p_value_format_id, value = @p_value, description = @p_description,
                    modified_at_utc = @now, version = version + 1
                WHERE
                    scope_code = @scope_code
                    AND ((@scope_id IS NULL AND scope_id IS NULL) OR scope_id = @scope_id)
                    AND name = @p_name;
                SET @version = @version + 1;
            END;

        -- namespace_id 1 is the seeded sys namespace (M001); detail identifies the setting by name.
        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message,
            detail_format_id, detail
        )
        VALUES (
            160 /* EventCode.SettingUpdated */, @now, COALESCE(@namespace_id, 1), @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, @definition_id, NULL, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message,
            1 /* JobPayloadFormat.Json */, CONVERT(VARBINARY(MAX), '{"name":"' + @p_name + '"}')
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
-- Version-CAS consume of an applied operator command: a miss means a newer command superseded the row
-- mid-apply and survives for the next tick. See IOutboxSignalStore.ConsumeAsync.
CREATE OR ALTER PROCEDURE acta.consume_outbox_signal
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_expected_version INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DELETE FROM acta.checkpoints
    WHERE
        job_id = @p_job_id
        AND kind_code = 20 /* JobCheckpointKindCode.Signal */
        AND name = @p_name
        AND version = @p_expected_version;

    SELECT CAST(@@ROWCOUNT AS BIGINT) AS consumed;
END
GO
-- The applying tick's read of one pending operator command; empty when the inbox slot is free.
CREATE OR ALTER PROCEDURE acta.get_outbox_signal
    @p_job_id BIGINT,
    @p_name VARCHAR(128)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT c.value_format_id, c.value, c.version
    FROM acta.checkpoints c
    WHERE
        c.job_id = @p_job_id
        AND c.kind_code = 20 /* JobCheckpointKindCode.Signal */
        AND c.name = @p_name
        AND c.status_code = 20 /* JobCheckpointStatusCode.Set */;
END
GO
-- Park admission for the sys.outbox operator inbox: insert when the slot is free, supersede when the
-- pending command has outlived the worker-dead window, reject otherwise. See IOutboxSignalStore.ParkAsync.
CREATE OR ALTER PROCEDURE acta.park_outbox_signal
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_value_format_id TINYINT,
    @p_value VARBINARY(MAX),
    @p_stale_before_utc DATETIME2(7)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @modified DATETIME2(7);

    BEGIN TRANSACTION;

    SELECT @modified = modified_at_utc
    FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
    WHERE job_id = @p_job_id AND kind_code = 20 /* JobCheckpointKindCode.Signal */ AND name = @p_name;

    IF @modified IS NULL
        INSERT INTO acta.checkpoints (
            job_id, kind_code, name, status_code, value_format_id, value,
            created_at_utc, modified_at_utc, version
        )
        VALUES (
            @p_job_id, 20 /* JobCheckpointKindCode.Signal */, @p_name, 20 /* JobCheckpointStatusCode.Set */,
            @p_value_format_id, @p_value, @now, @now, 0
        );
    ELSE IF @modified <= @p_stale_before_utc
        UPDATE acta.checkpoints
        SET
            status_code = 20 /* JobCheckpointStatusCode.Set */,
            value_format_id = @p_value_format_id,
            value = @p_value,
            modified_at_utc = @now,
            version = version + 1
        WHERE job_id = @p_job_id AND kind_code = 20 /* JobCheckpointKindCode.Signal */ AND name = @p_name;

    COMMIT TRANSACTION;

    /* The minted command id inside @p_value makes the payload unique, so value equality is the
       "my write landed" test; a losing park reads the incumbent's park instant as the rejection age. */
    SELECT
        CAST(CASE WHEN c.value = @p_value THEN 1 /* ControlAction.Applied */ ELSE 3 /* ControlAction.Rejected */ END AS SMALLINT)
            AS action,
        c.modified_at_utc AS pending_since_utc
    FROM acta.checkpoints c
    WHERE c.job_id = @p_job_id AND c.kind_code = 20 /* JobCheckpointKindCode.Signal */ AND c.name = @p_name;
END
GO
CREATE OR ALTER PROCEDURE acta.raise_signal
    @p_job_id BIGINT,
    @p_kind_code TINYINT,
    @p_name VARCHAR(128),
    @p_value_format_id TINYINT,
    @p_value VARBINARY(MAX),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_code TINYINT,
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @existing TINYINT;
    DECLARE
        @from_status TINYINT, @namespace_id SMALLINT, @lineage_root_id BIGINT,
        @definition_id INT, @tenant_id INT, @execution_number INT, @audit_level TINYINT,
        @job_ref UNIQUEIDENTIFIER;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @existing = status_code
        FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
        WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;

        SELECT
            @from_status = r.status_code,
            @namespace_id = j.namespace_id,
            @lineage_root_id = j.lineage_root_id,
            @definition_id = j.definition_id,
            @tenant_id = j.tenant_id,
            @execution_number = r.execution_number,
            @audit_level = j.audit_level_code,
            @job_ref = j.job_ref
        FROM acta.runtimes r WITH (UPDLOCK, ROWLOCK)
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE r.job_id = @p_job_id;

        IF @from_status IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* ControlAction.NotFound */ AS TINYINT) AS action,
                    CAST(NULL AS TINYINT) AS status_code;
                RETURN;
            END;

        IF @from_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* ControlAction.Rejected */ AS TINYINT) AS action,
                    @from_status AS status_code;
                RETURN;
            END;

        IF @existing IS NULL
            INSERT INTO acta.checkpoints (
                job_id, kind_code, name, status_code, value_format_id, value,
                created_at_utc, modified_at_utc, version
            )
            VALUES (@p_job_id, @p_kind_code, @p_name, 20 /* JobCheckpointStatusCode.Set */, @p_value_format_id, @p_value, @now, @now, 0);
        ELSE
            UPDATE acta.checkpoints
            SET
                status_code = 20 /* JobCheckpointStatusCode.Set */,
                value_format_id = @p_value_format_id,
                value = @p_value,
                modified_at_utc = @now,
                version = version + 1
            WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;

        IF @audit_level = 20 /* JobAuditLevelCode.Audit */
            INSERT INTO acta.events (
                event_code, created_at_utc, namespace_id,
                actor_code, actor_key,
                job_id, job_ref, execution_number,
                lineage_root_id, definition_id, tenant_id,
                worker_id,
                from_status_code, to_status_code,
                execution_status_code, duration_ms,
                reason_code, reason_message
            )
            VALUES (
                80 /* EventCode.JobSignalRaised */, @now, @namespace_id,
                @p_actor_code, @p_actor_key,
                @p_job_id, @job_ref, @execution_number,
                COALESCE(@lineage_root_id, @p_job_id), @definition_id, @tenant_id,
                NULL,
                @from_status, @from_status,
                NULL, NULL,
                @p_reason_code, @p_reason_message
            );

        IF @from_status = 20 /* JobStatusCode.Suspended */
            BEGIN
                UPDATE acta.runtimes
                SET
                    status_code = 10 /* JobStatusCode.Ready */,
                    next_run_at_utc = @now,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id;

                IF @audit_level = 20 /* JobAuditLevelCode.Audit */
                    INSERT INTO acta.events (
                        event_code, created_at_utc, namespace_id,
                        actor_code, actor_key,
                        job_id, job_ref, execution_number,
                        lineage_root_id, definition_id, tenant_id,
                        worker_id,
                        from_status_code, to_status_code,
                        execution_status_code, duration_ms,
                        reason_code, reason_message
                    )
                    VALUES (
                        72 /* EventCode.JobResumed */, @now, @namespace_id,
                        @p_actor_code, @p_actor_key,
                        @p_job_id, @job_ref, @execution_number,
                        COALESCE(@lineage_root_id, @p_job_id), @definition_id, @tenant_id,
                        NULL,
                        20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */,
                        NULL, NULL,
                        @p_reason_code, @p_reason_message
                    );

                COMMIT TRANSACTION;
                SELECT
                    CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
                    CAST(10 /* JobStatusCode.Ready */ AS TINYINT) AS status_code;
                RETURN;
            END

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* ControlAction.Applied */ AS TINYINT) AS action,
            @from_status AS status_code;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
-- Appends the applied-command evidence event against the sys.outbox slot job. Always emitted (no
-- audit-level gate): this is the trail for actions whose subject rows live in the producer's database.
CREATE OR ALTER PROCEDURE acta.record_outbox_event
    @p_job_id BIGINT,
    @p_event_code SMALLINT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        reason_message)
    SELECT
        @p_event_code,
        SYSUTCDATETIME(),
        j.namespace_id,
        @p_actor_code,
        @p_actor_key,
        j.id,
        j.job_ref,
        r.execution_number,
        COALESCE(j.lineage_root_id, j.id),
        j.definition_id,
        j.tenant_id,
        @p_reason_message
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = @p_job_id;
END
GO
CREATE OR ALTER PROCEDURE acta.wait_signal
    @p_job_id BIGINT,
    @p_kind_code TINYINT,
    @p_name VARCHAR(128)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @state TINYINT, @fmt TINYINT = 0;
    DECLARE @val VARBINARY(MAX) = NULL;
    DECLARE @outcome SMALLINT;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @state = status_code,
            @fmt = value_format_id,
            @val = value
        FROM acta.checkpoints WITH (UPDLOCK, HOLDLOCK)
        WHERE job_id = @p_job_id AND kind_code = @p_kind_code AND name = @p_name;

        IF @state = 20 /* JobCheckpointStatusCode.Set */
            BEGIN
                SET @outcome = 2 /* SignalWaitOutcomeCode.ContinueSet */;
            END
        ELSE
            BEGIN
                IF @state IS NULL
                    BEGIN
                        INSERT INTO acta.checkpoints (
                            job_id, kind_code, name, status_code, value_format_id, value,
                            created_at_utc, modified_at_utc, version
                        )
                        VALUES (
                            @p_job_id, @p_kind_code, @p_name, 10 /* JobCheckpointStatusCode.Pending */,
                            0 /* JobPayloadFormat.None */, NULL, @now, @now, 0
                        );
                    END
                SET @outcome = 1 /* SignalWaitOutcomeCode.SuspendPending */;
                SET @fmt = 0 /* JobPayloadFormat.None */;
                SET @val = NULL;
            END

        COMMIT TRANSACTION;
        SELECT
            @outcome AS outcome_code,
            @fmt AS value_format_id,
            @val AS value;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.start_execution
    @p_id BIGINT,
    @p_leased_by_worker_id INT,
    @p_execution_number INT,
    @p_version INT,
    @p_lease_ttl_seconds INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @action TINYINT;
    DECLARE @started TABLE (
        id BIGINT NOT NULL,
        job_ref UNIQUEIDENTIFIER NOT NULL,
        namespace_id SMALLINT NOT NULL,
        lineage_root_id BIGINT NULL,
        definition_id INT NOT NULL,
        tenant_id INT NULL,
        execution_number INT NOT NULL,
        audit_level_code TINYINT NOT NULL
    );

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE r
        SET
            status_code = 50 /* JobStatusCode.Executing */,
            lease_expires_at_utc = DATEADD(SECOND, @p_lease_ttl_seconds, @now),
            modified_at_utc = @now,
            version = r.version + 1
        OUTPUT
            INSERTED.job_id,
            j.job_ref,
            j.namespace_id,
            j.lineage_root_id,
            j.definition_id,
            j.tenant_id,
            INSERTED.execution_number,
            j.audit_level_code
        INTO @started
        FROM acta.runtimes r
        INNER JOIN acta.jobs j ON j.id = r.job_id
        WHERE
            r.job_id = @p_id
            AND r.execution_number = @p_execution_number
            AND r.version = @p_version
            AND r.status_code = 40 /* JobStatusCode.Dispatched */
            AND r.leased_by_worker_id = @p_leased_by_worker_id
            AND r.lease_expires_at_utc > @now;

        IF EXISTS (SELECT 1 FROM @started)
            BEGIN
                SET @action = 1 /* StartExecutionAction.Started */;

                INSERT INTO acta.events (
                    event_code, created_at_utc, namespace_id,
                    actor_code, actor_key,
                    job_id, job_ref, execution_number,
                    lineage_root_id, definition_id, tenant_id,
                    worker_id,
                    from_status_code, to_status_code,
                    execution_status_code, duration_ms,
                    reason_code, reason_message
                )
                SELECT
                    40 /* EventCode.JobExecutionStarted */,
                    @now,
                    st.namespace_id,
                    70 /* ActorCode.Worker */,
                    NULL,
                    st.id,
                    st.job_ref,
                    st.execution_number,
                    COALESCE(st.lineage_root_id, st.id),
                    st.definition_id,
                    st.tenant_id,
                    @p_leased_by_worker_id,
                    40 /* JobStatusCode.Dispatched */,
                    50 /* JobStatusCode.Executing */,
                    50 /* ExecutionStatusCode.Executing */,
                    NULL,
                    NULL,
                    NULL
                FROM @started st
                WHERE st.audit_level_code = 20 /* JobAuditLevelCode.Audit */;
            END
        ELSE
            BEGIN
                DECLARE @curWorker INT, @curEn INT, @curStatus TINYINT, @curVersion INT, @curLease DATETIME2(3);
                SELECT
                    @curEn = r.execution_number,
                    @curStatus = r.status_code,
                    @curVersion = r.version,
                    @curWorker = r.leased_by_worker_id,
                    @curLease = r.lease_expires_at_utc
                FROM acta.runtimes r
                WHERE r.job_id = @p_id;

                SET @action = CASE
                    WHEN
                        @curStatus IS NULL
                        OR @curStatus IN (
                            100 /* JobStatusCode.Succeeded */,
                            200 /* JobStatusCode.Failed */,
                            220 /* JobStatusCode.Cancelled */
                        )
                        THEN 4 /* StartExecutionAction.AlreadyTerminal */
                    WHEN @curWorker <> @p_leased_by_worker_id OR @curWorker IS NULL
                        THEN 2 /* StartExecutionAction.NotOwner */
                    WHEN @curEn <> @p_execution_number
                        THEN 3 /* StartExecutionAction.LostClaim */
                    WHEN @curVersion <> @p_version
                        THEN 3 /* StartExecutionAction.LostClaim */
                    WHEN @curStatus = 40 /* JobStatusCode.Dispatched */ AND @curLease <= @now
                        THEN 5 /* StartExecutionAction.LeaseExpired */
                    ELSE 4 /* StartExecutionAction.AlreadyTerminal */
                END;
            END

        COMMIT TRANSACTION;

        SELECT @action;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.start_step
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_at_most_once BIT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @outcome SMALLINT;
    DECLARE @attempt SMALLINT;
    DECLARE @version INT;
    DECLARE @next DATETIME2(3) = NULL;
    DECLARE @rfid TINYINT = 0;
    DECLARE @result VARBINARY(MAX) = NULL;
    DECLARE @rcode SMALLINT = NULL;
    DECLARE @rmsg NVARCHAR(512) = NULL;
    DECLARE @state TINYINT;
    DECLARE @existing_next DATETIME2(3);

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT
            @state = status_code,
            @attempt = attempt_number,
            @version = version,
            @existing_next = next_retry_at_utc,
            @rfid = result_format_id,
            @result = result,
            @rcode = reason_code,
            @rmsg = reason_message
        FROM acta.steps WITH (UPDLOCK, HOLDLOCK, INDEX (ux_steps_job_name))
        WHERE job_id = @p_job_id AND name = @p_name;

        IF @state IS NULL
            BEGIN
                INSERT INTO acta.steps (
                    job_id, name, status_code, attempt_number,
                    result_format_id, created_at_utc, modified_at_utc, version
                )
                VALUES (
                    @p_job_id, @p_name, 10 /* JobStepStatusCode.Pending */, 1,
                    0 /* JobPayloadFormat.None */, @now, @now, 0
                );

                SET @outcome = 1 /* StartStepOutcomeCode.Invoke */;
                SET @attempt = 1;
                SET @version = 0;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
                SET @next = NULL;
            END
        ELSE IF @state = 100 /* JobStepStatusCode.Succeeded */
            BEGIN
                SET @outcome = 3 /* StartStepOutcomeCode.ReplaySuccess */;
                SET @next = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE IF @state = 200 /* JobStepStatusCode.Exhausted */
            BEGIN
                SET @outcome = 4 /* StartStepOutcomeCode.Exhausted */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
            END
        ELSE IF @state = 230 /* JobStepStatusCode.Interrupted */
            BEGIN
            -- Terminal at-most-once ambiguity from an earlier replay; re-throw consistently, no mutation.
                SET @outcome = 5 /* StartStepOutcomeCode.Interrupted */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE IF @existing_next IS NOT NULL AND @existing_next > @now
            BEGIN
                SET @outcome = 2 /* StartStepOutcomeCode.Suspend */;
                SET @next = @existing_next;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE IF @p_at_most_once = 1
            BEGIN
            -- Pending slot re-entered on replay under AtMostOnce: the worker died after start_step recorded
            -- the pending row but before complete_step. Do not re-invoke; terminalize the row Interrupted
            -- (one transition, one version bump) and let the orchestration throw StepInterruptedException.
                UPDATE acta.steps
                SET
                    status_code = 230 /* JobStepStatusCode.Interrupted */,
                    reason_code = 63 /* JobEventReasonCode.JobStepInterrupted */,
                    reason_message = N'At-most-once step re-entered before completion; outcome unknown.',
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND name = @p_name;

                SET @version = @version + 1;
                SET @outcome = 5 /* StartStepOutcomeCode.Interrupted */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END
        ELSE
            BEGIN
                UPDATE acta.steps
                SET
                    attempt_number = attempt_number + 1,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND name = @p_name;

                SET @attempt = @attempt + 1;
                SET @version = @version + 1;
                SET @outcome = 1 /* StartStepOutcomeCode.Invoke */;
                SET @next = NULL;
                SET @rfid = 0 /* JobPayloadFormat.None */;
                SET @result = NULL;
                SET @rcode = NULL;
                SET @rmsg = NULL;
            END

        COMMIT TRANSACTION;

        SELECT
            @outcome AS outcome_code,
            @attempt AS attempt_number,
            @version AS version,
            @next AS next_retry_at_utc,
            @rfid AS result_format_id,
            @result AS result,
            @rcode AS reason_code,
            @rmsg AS reason_message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.register_tenant
    @p_tenant_key VARCHAR(128),
    @p_display_name NVARCHAR(128),
    @p_description NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    BEGIN TRY
        INSERT INTO acta.tenants
        (tenant_key, display_name, description, status_code, created_at_utc, modified_at_utc, version)
        SELECT
            @p_tenant_key,
            @p_display_name,
            @p_description,
            10 /* TenantStatusCode.Active */,
            @now,
            @now,
            0
        WHERE NOT EXISTS (
            SELECT 1 FROM acta.tenants
            WHERE tenant_key = @p_tenant_key
        );
    END TRY
    BEGIN CATCH
        -- A same-key race loses the guarded INSERT to a unique violation; the winner's row is the result.
        IF ERROR_NUMBER() NOT IN (2627, 2601)
            BEGIN
                THROW;
            END;
    END CATCH;

    SELECT id AS tenant_id FROM acta.tenants
    WHERE tenant_key = @p_tenant_key;
END;
GO
CREATE OR ALTER PROCEDURE acta.resume_tenant
    @p_tenant_key VARCHAR(128),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @id INT, @status TINYINT, @version INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT
            @id = t.id,
            @status = t.status_code,
            @version = t.version
        FROM acta.tenants t WITH (UPDLOCK, ROWLOCK)
        WHERE t.tenant_key = @p_tenant_key;

        IF @id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @status = 10 /* TenantStatusCode.Active */
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* AdminControlAction.AlreadyInState */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        UPDATE acta.tenants
        SET status_code = 10 /* TenantStatusCode.Active */, modified_at_utc = @now, version = version + 1
        WHERE id = @id;
        SET @version = @version + 1;

        -- namespace_id 1 is the seeded sys namespace (M001).
        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            11 /* EventCode.TenantResumed */, @now, 1, @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, NULL, @id, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.suspend_tenant
    @p_tenant_key VARCHAR(128),
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @id INT, @status TINYINT, @version INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT
            @id = t.id,
            @status = t.status_code,
            @version = t.version
        FROM acta.tenants t WITH (UPDLOCK, ROWLOCK)
        WHERE t.tenant_key = @p_tenant_key;

        IF @id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @status = 20 /* TenantStatusCode.Suspended */
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(3 /* AdminControlAction.AlreadyInState */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        UPDATE acta.tenants
        SET status_code = 20 /* TenantStatusCode.Suspended */, modified_at_utc = @now, version = version + 1
        WHERE id = @id;
        SET @version = @version + 1;

        -- namespace_id 1 is the seeded sys namespace (M001).
        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            10 /* EventCode.TenantSuspended */, @now, 1, @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, NULL, @id, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.update_tenant
    @p_tenant_key VARCHAR(128),
    @p_display_name NVARCHAR(128),
    @p_description NVARCHAR(512),
    @p_expected_version INT,
    @p_actor_code TINYINT,
    @p_actor_key VARCHAR(128),
    @p_reason_message NVARCHAR(512)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @id INT, @version INT;
    BEGIN TRY
        BEGIN TRANSACTION;
        SELECT
            @id = t.id,
            @version = t.version
        FROM acta.tenants t WITH (UPDLOCK, ROWLOCK)
        WHERE t.tenant_key = @p_tenant_key;

        IF @id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(2 /* AdminControlAction.NotFound */ AS SMALLINT) AS action,
                    CAST(NULL AS INT) AS version;
                RETURN;
            END;

        IF @version <> @p_expected_version
            BEGIN
                COMMIT TRANSACTION;
                SELECT
                    CAST(4 /* AdminControlAction.VersionConflict */ AS SMALLINT) AS action,
                    @version AS version;
                RETURN;
            END;

        UPDATE acta.tenants
        SET display_name = @p_display_name, description = @p_description, modified_at_utc = @now, version = version + 1
        WHERE id = @id;
        SET @version = @version + 1;

        -- namespace_id 1 is the seeded sys namespace (M001).
        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key,
            job_id, job_ref, execution_number, lineage_root_id, definition_id, tenant_id, worker_id,
            from_status_code, to_status_code, execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            12 /* EventCode.TenantUpdated */, @now, 1, @p_actor_code, @p_actor_key,
            NULL, NULL, NULL, NULL, NULL, @id, NULL,
            NULL, NULL, NULL, NULL, NULL, @p_reason_message
        );

        COMMIT TRANSACTION;
        SELECT
            CAST(1 /* AdminControlAction.Applied */ AS SMALLINT) AS action,
            @version AS version;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.arm_or_consume_sleep_timer
    @p_job_id BIGINT,
    @p_name VARCHAR(128),
    @p_delay_seconds INT = NULL,
    @p_resume_at_utc DATETIME2(3) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @due DATETIME2(3) = COALESCE(@p_resume_at_utc, DATEADD(SECOND, @p_delay_seconds, @now));
    DECLARE @outcome SMALLINT;
    DECLARE @result_due DATETIME2(3) = NULL;
    DECLARE @existing_state TINYINT;
    DECLARE @existing_due DATETIME2(3);
    DECLARE @lock_id BIGINT;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @lock_id = job_id
        FROM acta.runtimes WITH (UPDLOCK, HOLDLOCK)
        WHERE job_id = @p_job_id;

        SELECT
            @existing_state = status_code,
            @existing_due = due_at_utc
        FROM acta.checkpoints
        WHERE
            job_id = @p_job_id
            AND kind_code = 30 /* JobCheckpointKindCode.Timer */
            AND name = @p_name;

        IF @existing_state = 10 /* JobCheckpointStatusCode.Pending */ AND @existing_due > @now
            BEGIN

                SET @outcome = 1 /* SleepOutcome.Suspend */;
                SET @result_due = @existing_due;
            END
        ELSE IF @existing_state = 10 /* JobCheckpointStatusCode.Pending */
            BEGIN

                UPDATE acta.checkpoints
                SET
                    status_code = 100 /* JobCheckpointStatusCode.Consumed */,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id AND kind_code = 30 /* JobCheckpointKindCode.Timer */ AND name = @p_name;

                UPDATE acta.runtimes
                SET
                    next_run_at_utc = NULL,
                    modified_at_utc = @now,
                    version = version + 1
                WHERE job_id = @p_job_id;

                SET @outcome = 2 /* SleepOutcome.Continue */;
            END
        ELSE IF @existing_state IS NOT NULL
            BEGIN

                SET @outcome = 2 /* SleepOutcome.Continue */;
            END
        ELSE IF @due <= @now
            BEGIN

                SET @outcome = 2 /* SleepOutcome.Continue */;
            END
        ELSE IF
            EXISTS (
                SELECT 1 FROM acta.checkpoints
                WHERE
                    job_id = @p_job_id AND kind_code = 30 /* JobCheckpointKindCode.Timer */ AND status_code = 10
            /* JobCheckpointStatusCode.Pending */
            )
            BEGIN
                SET @outcome = 3 /* SleepOutcome.Reject */;
            END
        ELSE
            BEGIN
                INSERT INTO acta.checkpoints (
                    job_id, kind_code, name, status_code, due_at_utc,
                    created_at_utc, modified_at_utc, version
                )
                VALUES (
                    @p_job_id, 30 /* JobCheckpointKindCode.Timer */, @p_name, 10 /* JobCheckpointStatusCode.Pending */, @due,
                    @now, @now, 0
                );

                SET @outcome = 1 /* SleepOutcome.Suspend */;
                SET @result_due = @due;
            END

        COMMIT TRANSACTION;

        SELECT
            @outcome AS outcome_code,
            @result_due AS due_at_utc;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.extend_worker_leases
    @p_leased_by_worker_id INT,
    @p_lease_ttl_seconds INT,
    @p_draining BIT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();

    UPDATE acta.workers
    SET
        last_seen_at_utc = @now,
        status_code = CASE
            WHEN @p_draining = 1 AND status_code = 10 /* WorkerStatusCode.Active */
                THEN 80 /* WorkerStatusCode.Draining */
            ELSE status_code
        END,
        modified_at_utc = @now,
        version = version + 1
    WHERE id = @p_leased_by_worker_id;

    /* Push every in-flight execution lease forward. Deliberately no version bump: a lease refresh
       is not a claim-generation change, so a buffered claim still passes the start CAS. */
    UPDATE acta.runtimes
    SET lease_expires_at_utc = DATEADD(SECOND, @p_lease_ttl_seconds, @now)
    OUTPUT INSERTED.job_id
    WHERE
        leased_by_worker_id = @p_leased_by_worker_id
        AND status_code IN (40 /* JobStatusCode.Dispatched */, 50 /* JobStatusCode.Executing */);
END;
GO
CREATE OR ALTER PROCEDURE acta.mark_dead_workers
    @p_dead_after_seconds INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @marked TABLE (id INT NOT NULL PRIMARY KEY, namespace_id SMALLINT NOT NULL, worker_ref UNIQUEIDENTIFIER NOT NULL);

    UPDATE acta.workers WITH (ROWLOCK, READPAST)
    SET
        status_code = 200 /* WorkerStatusCode.Dead */,
        modified_at_utc = SYSUTCDATETIME(),
        version = version + 1
    OUTPUT INSERTED.id, INSERTED.namespace_id, INSERTED.worker_ref INTO @marked (id, namespace_id, worker_ref)
    WHERE
        status_code = 10 /* WorkerStatusCode.Active */
        AND last_seen_at_utc < DATEADD(SECOND, -@p_dead_after_seconds, SYSUTCDATETIME());

    INSERT INTO acta.events (
        event_code, created_at_utc, namespace_id, actor_code, actor_key, job_id, execution_number,
        lineage_root_id, definition_id, worker_id, from_status_code, to_status_code,
        execution_status_code, duration_ms, reason_code, reason_message
    )
    SELECT
        122 /* EventCode.WorkerDied */,
        SYSUTCDATETIME(),
        m.namespace_id,
        70 /* ActorCode.Worker */,
        LOWER(CONVERT(varchar(36), m.worker_ref)),
        NULL,
        NULL,
        NULL,
        NULL,
        m.id,
        NULL,
        NULL,
        NULL,
        NULL,
        101 /* JobEventReasonCode.WorkerHeartbeatStale */,
        NULL
    FROM @marked m;

    SELECT COUNT(*) FROM @marked;
END;
GO
CREATE OR ALTER PROCEDURE acta.start_worker
    @p_name VARCHAR(128),
    @p_owner_team NVARCHAR(512),
    @p_description NVARCHAR(512),
    @p_catalog_hash VARCHAR(128),
    @p_status_code TINYINT,
    @p_deployment_version VARCHAR(128),
    @p_host VARCHAR(256),
    @p_engine_version VARCHAR(128),
    @p_dotnet_version VARCHAR(64),
    @p_process_id INT,
    @p_max_concurrency INT,
    @p_worker_ref UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @ns_id SMALLINT;
    DECLARE @worker_id INT;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE acta.namespaces
        SET
            owner_team = @p_owner_team,
            description = @p_description,
            catalog_hash = @p_catalog_hash,
            modified_at_utc = @now,
            version = version + 1
        WHERE
            name = @p_name
            AND (catalog_hash <> @p_catalog_hash OR catalog_hash IS NULL);

        INSERT INTO acta.namespaces
        (name, owner_team, description, catalog_hash, status_code, created_at_utc, modified_at_utc, version)
        SELECT
            @p_name,
            @p_owner_team,
            @p_description,
            @p_catalog_hash,
            @p_status_code,
            @now,
            @now,
            0
        WHERE NOT EXISTS (
            SELECT 1 FROM acta.namespaces
            WHERE name = @p_name
        );

        SELECT @ns_id = id FROM acta.namespaces
        WHERE name = @p_name;

        INSERT INTO acta.workers
        (
            namespace_id,
            worker_ref,
            status_code,
            deployment_version,
            host,
            engine_version,
            dotnet_version,
            process_id,
            max_concurrency,
            last_seen_at_utc,
            created_at_utc,
            modified_at_utc,
            version
        )
        VALUES
        (
            @ns_id,
            @p_worker_ref,
            10 /* WorkerStatusCode.Active */,
            @p_deployment_version,
            @p_host,
            @p_engine_version,
            @p_dotnet_version,
            @p_process_id,
            @p_max_concurrency,
            @now,
            @now,
            @now,
            0
        );
        SET @worker_id = CAST(SCOPE_IDENTITY() AS INT);

        INSERT INTO acta.events (
            event_code, created_at_utc, namespace_id, actor_code, actor_key, job_id, execution_number,
            lineage_root_id, definition_id, worker_id, from_status_code, to_status_code,
            execution_status_code, duration_ms, reason_code, reason_message
        )
        VALUES (
            120 /* EventCode.WorkerStarted */, @now, @ns_id, 70 /* ActorCode.Worker */, LOWER(CONVERT(varchar(36), @p_worker_ref)),
            NULL, NULL, NULL, NULL, @worker_id, NULL, NULL, NULL, NULL, NULL, NULL
        );

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            BEGIN
                ROLLBACK TRANSACTION;
            END;

        THROW;
    END CATCH;

    SELECT
        @ns_id AS namespace_id,
        @worker_id AS worker_id;
END;
GO
CREATE OR ALTER PROCEDURE acta.stop_worker
    @p_namespace_id SMALLINT,
    @p_worker_id INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @stopped TABLE (id INT NOT NULL PRIMARY KEY, worker_ref UNIQUEIDENTIFIER NOT NULL);

    UPDATE acta.workers
    SET
        status_code = 100 /* WorkerStatusCode.Stopped */,
        modified_at_utc = @now,
        version = version + 1
    OUTPUT INSERTED.id, INSERTED.worker_ref INTO @stopped (id, worker_ref)
    WHERE
        id = @p_worker_id
        AND status_code IN (10 /* WorkerStatusCode.Active */, 80 /* WorkerStatusCode.Draining */);

    INSERT INTO acta.events (
        event_code, created_at_utc, namespace_id, actor_code, actor_key, job_id, execution_number,
        lineage_root_id, definition_id, worker_id, from_status_code, to_status_code,
        execution_status_code, duration_ms, reason_code, reason_message
    )
    SELECT
        121 /* EventCode.WorkerStopped */,
        @now,
        @p_namespace_id,
        70 /* ActorCode.Worker */,
        LOWER(CONVERT(varchar(36), s.worker_ref)),
        NULL,
        NULL,
        NULL,
        NULL,
        s.id,
        NULL,
        NULL,
        NULL,
        NULL,
        100 /* JobEventReasonCode.WorkerCleanShutdown */,
        NULL
    FROM @stopped s;
END;
GO
CREATE OR ALTER PROCEDURE acta.purge_expired_data
    @p_namespace_id SMALLINT,
    @p_events_retention_days INT,
    @p_alert_retention_days INT,
    @p_worker_retention_seconds INT,
    @p_batch_size INT,
    @p_max_iterations INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @jobs_deleted INT = 0, @events_deleted INT = 0, @alerts_deleted INT = 0, @workers_deleted INT = 0, @locks_deleted INT = 0;
    DECLARE @rows INT, @iter INT;
    DECLARE @del TABLE (id BIGINT NOT NULL);
    DECLARE @schedule_del TABLE (id BIGINT NOT NULL);
    DECLARE @lock_del TABLE (lock_key VARCHAR(256) NOT NULL);

    SET @rows = 1;
    SET @iter = 0;
    WHILE @rows > 0 AND @iter < @p_max_iterations
        BEGIN
            DELETE @del;
            BEGIN TRANSACTION;
            INSERT INTO @del (id)
            SELECT TOP (@p_batch_size) j.id
            FROM acta.runtimes r WITH (UPDLOCK, READPAST)
            INNER JOIN acta.jobs j WITH (UPDLOCK, READPAST) ON j.id = r.job_id
            WHERE
                r.namespace_id = @p_namespace_id
                AND r.status_code IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                AND r.retention_until_utc IS NOT NULL
                AND r.retention_until_utc <= @now
                -- Lineage guard: parent_id carries no FK, so purging a parent whose children still
                -- exist would orphan their lineage (same rule as the manual purge_job). Only leaves
                -- delete; a fully-expired subtree drains bottom-up across iterations.
                AND NOT EXISTS (
                    SELECT 1 FROM acta.jobs c
                    WHERE c.parent_id = j.id
                )
            ORDER BY r.retention_until_utc, r.job_id;

            DELETE @schedule_del;
            INSERT INTO @schedule_del (id)
            SELECT s.id FROM acta.schedules s WITH (UPDLOCK)
            WHERE s.job_id IN (SELECT id FROM @del);

            DELETE FROM acta.tags
            WHERE
                (scope_code = 50 /* TagScopeCode.Job */ AND scope_id IN (SELECT id FROM @del))
                OR (scope_code = 60 /* TagScopeCode.Schedule */ AND scope_id IN (SELECT id FROM @schedule_del));

            DELETE FROM acta.checkpoints
            WHERE job_id IN (SELECT id FROM @del);
            DELETE FROM acta.runtimes
            WHERE job_id IN (SELECT id FROM @del);
            DELETE FROM acta.steps
            WHERE job_id IN (SELECT id FROM @del);
            DELETE FROM acta.results
            WHERE job_id IN (SELECT id FROM @del);
            DELETE FROM acta.jobs
            WHERE id IN (SELECT id FROM @del);
            SET @rows = (SELECT COUNT(*) FROM @del);
            COMMIT TRANSACTION;
            SET @jobs_deleted = @jobs_deleted + @rows;
            SET @iter = @iter + 1;
        END;

    DECLARE @events_cutoff DATETIME2(7) = DATEADD(DAY, -@p_events_retention_days, @now);
    SET @rows = 1;
    SET @iter = 0;
    WHILE @rows > 0 AND @iter < @p_max_iterations
        BEGIN
            DELETE @del;
            BEGIN TRANSACTION;
            INSERT INTO @del (id)
            SELECT TOP (@p_batch_size) id
            FROM acta.events WITH (UPDLOCK, READPAST)
            WHERE
                namespace_id = @p_namespace_id
                AND created_at_utc <= @events_cutoff
            ORDER BY created_at_utc, id;
            DELETE FROM acta.tags
            WHERE scope_code = 90 /* TagScopeCode.Event */ AND scope_id IN (SELECT id FROM @del);
            DELETE e FROM acta.events e INNER JOIN @del d ON d.id = e.id;
            SET @rows = (SELECT COUNT(*) FROM @del);
            COMMIT TRANSACTION;
            SET @events_deleted = @events_deleted + @rows;
            SET @iter = @iter + 1;
        END;

    DECLARE @alerts_cutoff DATETIME2(7) = DATEADD(DAY, -@p_alert_retention_days, @now);
    SET @rows = 1;
    SET @iter = 0;
    WHILE @rows > 0 AND @iter < @p_max_iterations
        BEGIN
            DELETE @del;
            BEGIN TRANSACTION;
            INSERT INTO @del (id)
            SELECT TOP (@p_batch_size) id
            FROM acta.alerts WITH (UPDLOCK, READPAST)
            WHERE
                namespace_id = @p_namespace_id
                AND created_at_utc <= @alerts_cutoff
                AND delivery_status_code IN (
                    30 /* AlertDeliveryStatusCode.Suppressed */,
                    100 /* AlertDeliveryStatusCode.Delivered */,
                    200 /* AlertDeliveryStatusCode.Failed */
                )
            ORDER BY created_at_utc, id;
            DELETE FROM acta.tags
            WHERE scope_code = 80 /* TagScopeCode.Alert */ AND scope_id IN (SELECT id FROM @del);
            DELETE a FROM acta.alerts a INNER JOIN @del d ON d.id = a.id;
            SET @rows = (SELECT COUNT(*) FROM @del);
            COMMIT TRANSACTION;
            SET @alerts_deleted = @alerts_deleted + @rows;
            SET @iter = @iter + 1;
        END;

    DECLARE @worker_cutoff DATETIME2(7) = DATEADD(SECOND, -@p_worker_retention_seconds, @now);
    SET @rows = 1;
    SET @iter = 0;
    WHILE @rows > 0 AND @iter < @p_max_iterations
        BEGIN
            DELETE @del;
            BEGIN TRANSACTION;
            INSERT INTO @del (id)
            SELECT TOP (@p_batch_size) id
            FROM acta.workers WITH (UPDLOCK, READPAST)
            WHERE
                namespace_id = @p_namespace_id
                AND status_code IN (100 /* WorkerStatusCode.Stopped */, 200 /* WorkerStatusCode.Dead */)
                AND last_seen_at_utc <= @worker_cutoff
            ORDER BY last_seen_at_utc, id;
            DELETE FROM acta.tags
            WHERE scope_code = 70 /* TagScopeCode.Worker */ AND scope_id IN (SELECT id FROM @del);
            DELETE w FROM acta.workers w INNER JOIN @del d ON d.id = w.id;
            SET @rows = (SELECT COUNT(*) FROM @del);
            COMMIT TRANSACTION;
            SET @workers_deleted = @workers_deleted + @rows;
            SET @iter = @iter + 1;
        END;

    SET @rows = 1;
    SET @iter = 0;
    WHILE @rows > 0 AND @iter < @p_max_iterations
        BEGIN
        -- Stage the batch first (same shape as the sections above), so the READPAST probe runs
        -- exactly once per iteration and the delete stays within the batch size.
            DELETE @lock_del;
            INSERT INTO @lock_del (lock_key)
            SELECT TOP (@p_batch_size) lock_key
            FROM acta.locks WITH (UPDLOCK, READPAST)
            WHERE
                expires_at_utc <= @now
            ORDER BY expires_at_utc;
            DELETE t FROM acta.locks t INNER JOIN @lock_del d ON d.lock_key = t.lock_key;
            SET @rows = @@ROWCOUNT;
            SET @locks_deleted = @locks_deleted + @rows;
            SET @iter = @iter + 1;
        END;

    SELECT
        @jobs_deleted AS jobs_deleted,
        @events_deleted AS events_deleted,
        @alerts_deleted AS alerts_deleted,
        @workers_deleted AS workers_deleted,
        @locks_deleted AS locks_deleted;
END;
GO
CREATE OR ALTER PROCEDURE acta.apply_tags
    @p_scope_code TINYINT,
    @p_lookup_id BIGINT,
    @p_lookup_name VARCHAR(128),
    @p_mutation TINYINT,
    @p_items_json NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @scope_id BIGINT, @namespace_id SMALLINT;
    DECLARE @items TABLE (
        name VARCHAR(128) NOT NULL PRIMARY KEY,
        value NVARCHAR(128) NULL,
        value_search NVARCHAR(128) NULL
    );

    INSERT INTO @items (name, value, value_search)
    SELECT
        name,
        value,
        value_search
    FROM
        OPENJSON (@p_items_json)
        WITH (
            name VARCHAR(128) '$.name',
            value NVARCHAR(128) '$.value',
            value_search NVARCHAR(128) '$.value_search'
        );

    BEGIN TRY
        BEGIN TRANSACTION;

        IF @p_scope_code = 20 /* TagScopeCode.Tenant */
            SELECT
                @scope_id = CONVERT(BIGINT, t.id),
                @namespace_id = NULL
            FROM acta.tenants t WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE t.tenant_key = @p_lookup_name;
        ELSE IF @p_scope_code = 30 /* TagScopeCode.Namespace */
            SELECT
                @scope_id = CONVERT(BIGINT, n.id),
                @namespace_id = n.id
            FROM acta.namespaces n WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE n.name = @p_lookup_name;
        ELSE IF @p_scope_code = 40 /* TagScopeCode.Definition */
            SELECT
                @scope_id = CONVERT(BIGINT, d.id),
                @namespace_id = d.namespace_id
            FROM acta.definitions d WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE d.id = @p_lookup_id;
        ELSE IF @p_scope_code = 50 /* TagScopeCode.Job */
            SELECT
                @scope_id = j.id,
                @namespace_id = j.namespace_id
            FROM acta.jobs j WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE j.id = @p_lookup_id;
        ELSE IF @p_scope_code = 60 /* TagScopeCode.Schedule */
            SELECT
                @scope_id = s.id,
                @namespace_id = s.namespace_id
            FROM acta.schedules s WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE s.job_id = @p_lookup_id AND s.name = @p_lookup_name;
        ELSE IF @p_scope_code = 70 /* TagScopeCode.Worker */
            SELECT
                @scope_id = CONVERT(BIGINT, w.id),
                @namespace_id = w.namespace_id
            FROM acta.workers w WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE w.id = @p_lookup_id;
        ELSE IF @p_scope_code = 80 /* TagScopeCode.Alert */
            SELECT
                @scope_id = a.id,
                @namespace_id = a.namespace_id
            FROM acta.alerts a WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE a.id = @p_lookup_id;
        ELSE IF @p_scope_code = 90 /* TagScopeCode.Event */
            SELECT
                @scope_id = e.id,
                @namespace_id = e.namespace_id
            FROM acta.events e WITH (UPDLOCK, HOLDLOCK, ROWLOCK)
            WHERE e.id = @p_lookup_id;
        ELSE
            THROW 50000, 'Unsupported tag scope code.', 1;

        IF @scope_id IS NULL
            BEGIN
                COMMIT TRANSACTION;
                SELECT CAST(2 /* TagMutationAction.NotFound */ AS TINYINT) AS action;
                RETURN;
            END;

        IF @p_mutation = 1 /* TagMutationKind.Replace */
            BEGIN
                DELETE FROM acta.tags
                WHERE scope_code = @p_scope_code AND scope_id = @scope_id;

                INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
                SELECT
                    @p_scope_code,
                    @scope_id,
                    @namespace_id,
                    name,
                    value,
                    value_search
                FROM @items;
            END
        ELSE IF @p_mutation = 2 /* TagMutationKind.Upsert */
            BEGIN
                IF
                    EXISTS (
                        SELECT 1 FROM @items i
                        WHERE NOT EXISTS (
                            SELECT 1 FROM acta.tags t
                            WHERE t.scope_code = @p_scope_code AND t.scope_id = @scope_id AND t.name = i.name
                        )
                    )
                    AND (
                        SELECT COUNT(*) FROM acta.tags t
                        WHERE t.scope_code = @p_scope_code AND t.scope_id = @scope_id
                    ) >= 32
                    THROW 50000, 'A target may carry at most 32 tags.', 1;

                UPDATE t
                SET namespace_id = @namespace_id, value = i.value, value_search = i.value_search
                FROM acta.tags t
                JOIN @items i ON i.name = t.name
                WHERE t.scope_code = @p_scope_code AND t.scope_id = @scope_id;

                INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
                SELECT
                    @p_scope_code,
                    @scope_id,
                    @namespace_id,
                    i.name,
                    i.value,
                    i.value_search
                FROM @items i
                WHERE NOT EXISTS (
                    SELECT 1 FROM acta.tags t
                    WHERE t.scope_code = @p_scope_code AND t.scope_id = @scope_id AND t.name = i.name
                );
            END
        ELSE IF @p_mutation = 3 /* TagMutationKind.Remove */
            BEGIN
                DELETE t
                FROM acta.tags t
                JOIN @items i ON i.name = t.name
                WHERE t.scope_code = @p_scope_code AND t.scope_id = @scope_id;
            END
        ELSE
            THROW 50000, 'Unsupported tag mutation code.', 1;

        COMMIT TRANSACTION;
        SELECT CAST(1 /* TagMutationAction.Applied */ AS TINYINT) AS action;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH;
END;
GO
CREATE OR ALTER PROCEDURE acta.acquire_lock
    @p_lock_key VARCHAR(256),
    @p_job_id BIGINT,
    @p_lease_ttl_seconds INT,
    @p_hold_token UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @now DATETIME2(7) = SYSUTCDATETIME();
    DECLARE @out TABLE (hold_token UNIQUEIDENTIFIER);

    /* Steal-or-insert without MERGE HOLDLOCK: the point UPDATE takes only a key lock, and the
       insert race for a brand-new key is settled by the primary key (a loser lands on 2627/2601
       and reports not-acquired) instead of serializable range locks that deadlock same-gap inserts. */
    UPDATE acta.locks
    SET
        job_id = @p_job_id,
        expires_at_utc = DATEADD(SECOND, @p_lease_ttl_seconds, @now),
        hold_token = @p_hold_token
    OUTPUT INSERTED.hold_token INTO @out
    WHERE
        lock_key = @p_lock_key
        AND expires_at_utc <= @now;

    IF
        @@ROWCOUNT = 0 AND NOT EXISTS (
            SELECT 1 FROM acta.locks
            WHERE lock_key = @p_lock_key
        )
        BEGIN
            BEGIN TRY
                INSERT INTO acta.locks (lock_key, job_id, expires_at_utc, hold_token)
                OUTPUT INSERTED.hold_token INTO @out
                VALUES (@p_lock_key, @p_job_id, DATEADD(SECOND, @p_lease_ttl_seconds, @now), @p_hold_token);
            END TRY
            BEGIN CATCH
                IF ERROR_NUMBER() NOT IN (2627, 2601)
                    BEGIN
                        THROW;
                    END;
            END CATCH;
        END;

    SELECT hold_token FROM @out;
END;
GO
CREATE OR ALTER PROCEDURE acta.extend_lock
    @p_lock_key VARCHAR(256),
    @p_hold_token UNIQUEIDENTIFIER,
    @p_lease_ttl_seconds INT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE acta.locks
    SET expires_at_utc = DATEADD(SECOND, @p_lease_ttl_seconds, SYSUTCDATETIME())
    OUTPUT INSERTED.hold_token
    WHERE lock_key = @p_lock_key AND hold_token = @p_hold_token;
END;
GO
CREATE OR ALTER PROCEDURE acta.release_lock
    @p_lock_key VARCHAR(256),
    @p_hold_token UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;

    DELETE FROM acta.locks
    OUTPUT DELETED.hold_token
    WHERE lock_key = @p_lock_key AND hold_token = @p_hold_token;
END;
GO
COMMIT TRANSACTION;
GO
